LEARN.technique({id:"palm-muting",name:"Palm muting",family:"Rhythm",level:"Beginner",instr:"guitar",summary:'Rest the outer edge of your picking hand on the strings right at the bridge, and every note comes out shorter and thicker. Moving the hand and changing the weight turns it from a light damp into a tight "chug".',how:['Rest the fleshy outer edge of your picking hand, the "karate chop" part below the pinky, lightly across the strings where they meet the bridge saddles.',"Pick the open low E. If it thuds with no clear pitch, your hand is too far toward the neck: slide it back toward the bridge in small steps until the note returns.","Treat position and weight as a dial. Closer to the neck or a little more weight gives a short, percussive chug. Closer to the bridge gives a fuller note with more sustain.","Keep the hand resting there and pick from the wrist. Start with downstrokes on eighth notes so the mute stays even from note to note.","Lift the hand slightly to let a chosen note or chord ring, then set it back down. Switching between muted and open strokes is how riffs get their accents.",'In tab, palm muting is marked "P.M." with a dashed line. The mute lasts until the line ends.'],mistakes:["Hand too far forward, over the pickups: notes go dead and lose their pitch. Creep back toward the saddles until you hear the note again.","Pressing down hard: the note chokes. A light touch, with the hand resting rather than pushing, is enough.","Resting behind the bridge: nothing gets muted. The contact point is on the strings just in front of the saddles.","Lifting the whole arm to unmute: keep the movement small so the hand lands in the same spot every time."],used:'Metal and hard rock chugs (Black Sabbath\'s "Paranoid", Metallica\'s "The Four Horsemen"), punk (Green Day\'s "Basket Case"), post-punk bands such as Gang of Four and Talking Heads, disco parts played through a wah, and clean surf and rock rhythm parts. Folk and acoustic fingerpickers use it too.',sources:[{id:"s1",title:"How to Palm Mute on Guitar for Perfect Rock and Metal Tone",site:"TrueFire",url:"https://truefire.com/learn/how-to-palm-mute-on-guitar",kind:"lesson"},{id:"s2",title:"Palm mute",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Palm_mute",kind:"encyclopedia"},{id:"s3",title:"Clean Up Your Technique!",author:"Sam Bell",site:"Premier Guitar",year:2025,url:"https://www.premierguitar.com/lessons/clean-up-your-technique",kind:"lesson"},{id:"s4",title:"Palm Mute Guitar for Beginners",site:"fretjam",url:"https://fretjam.com/palm-mute-guitar.html",kind:"lesson"},{id:"s5",title:"Palm Muting (glossary)",site:"LickLibrary",url:"https://www.licklibrary.com/glossary/palm-muting",kind:"lesson"},{id:"s6",title:"Ending Sonic Pollution: How to Make Simple Things Sound Good",author:"Rob Michael",site:"Premier Guitar",year:2022,url:"https://www.premierguitar.com/lessons/beginner/how-to-palm-mute",kind:"lesson"}],study:[{title:"How to Palm Mute Your Guitar",kind:"video",author:"Nate Savage (Guitareo)",url:"https://guitarlessons.com/guitar-lessons/guitar-technique/how-to-palm-mute-guitar/",note:"Shows over-muting and under-muting side by side, so you can hear the sweet spot."},{title:"Metal Rhythm Guitar, Vol. 1",kind:"book",author:"Troy Stetina",note:"A long-running method for palm-muted metal rhythm, with graded riffs and picking drills."},{title:"Paranoid (1970)",kind:"album",author:"Black Sabbath",note:"The title track is a textbook example of sustained palm-muted rhythm."},{title:"Master of Puppets (1986)",kind:"album",author:"Metallica",note:"Tight muted chugs against ringing chords, all through the record."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"palm-muting-open-e",title:"Open E chugs with open accents",instr:"guitar",bpm:100,grid:2,notes:[[0,6,0,1,"pm,D"],[1,6,0,1,"pm,D"],[2,6,0,1,"pm,D"],[3,6,0,1,"pm,D"],[4,6,0,1,"pm,D"],[5,6,0,1,"pm,D"],[6,6,3,2,"D,acc"],[6,5,5,2,"D,acc"],[8,6,0,1,"pm,D"],[9,6,0,1,"pm,D"],[10,6,0,1,"pm,D"],[11,6,0,1,"pm,D"],[12,6,0,1,"pm,D"],[13,6,0,1,"pm,D"],[14,5,0,2,"D,acc"],[14,4,2,2,"D,acc"]],note:"Keep the hand on the strings for the open E, then lift it for the power chord at the end of each bar. Listen for the jump in volume and length between the two.",cites:["s1","s4"]},{type:"tab",id:"palm-muting-power-chords",title:"Muted and open power chords",instr:"guitar",bpm:112,grid:2,notes:[[0,6,0,1,"pm,D"],[0,5,2,1,"pm,D"],[1,6,0,1,"pm,D"],[1,5,2,1,"pm,D"],[2,6,0,1,"pm,D"],[2,5,2,1,"pm,D"],[3,6,0,1,"pm,D"],[3,5,2,1,"pm,D"],[4,6,3,2,"D,acc"],[4,5,5,2,"D,acc"],[6,6,0,1,"pm,D"],[6,5,2,1,"pm,D"],[7,6,0,1,"pm,D"],[7,5,2,1,"pm,D"],[8,6,0,1,"pm,D"],[8,5,2,1,"pm,D"],[9,6,0,1,"pm,D"],[9,5,2,1,"pm,D"],[10,6,0,1,"pm,D"],[10,5,2,1,"pm,D"],[11,6,0,1,"pm,D"],[11,5,2,1,"pm,D"],[12,5,5,2,"D,acc"],[12,4,7,2,"D,acc"],[14,5,3,2,"D,acc"],[14,4,5,2,"D,acc"]],note:"All downstrokes. The muted E5s should sound tight and even, while G5, D5 and C5 ring for their full length, so lift the hand exactly on those beats."},{type:"tab",id:"palm-muting-pedal",title:"Sixteenth-note pedal riff",instr:"guitar",bpm:90,grid:4,notes:[[0,6,0,1,"pm,D"],[1,6,0,1,"pm,U"],[2,6,0,1,"pm,D"],[3,6,0,1,"pm,U"],[4,6,0,1,"pm,D"],[5,6,0,1,"pm,U"],[6,5,2,2,"D,acc"],[8,6,0,1,"pm,D"],[9,6,0,1,"pm,U"],[10,6,0,1,"pm,D"],[11,6,0,1,"pm,U"],[12,5,3,2,"D,acc"],[14,5,2,2,"D,acc"],[16,6,0,1,"pm,D"],[17,6,0,1,"pm,U"],[18,6,0,1,"pm,D"],[19,6,0,1,"pm,U"],[20,6,0,1,"pm,D"],[21,6,0,1,"pm,U"],[22,5,5,2,"D,acc"],[24,6,0,1,"pm,D"],[25,6,0,1,"pm,U"],[26,6,0,1,"pm,D"],[27,6,0,1,"pm,U"],[28,5,3,2,"D,acc"],[30,5,2,2,"D,acc"]],note:"Strict alternate picking: down on the beat, up in between. The muted open E keeps the pulse and the unmuted notes on the A string carry the melody."}]}),LEARN.technique({id:"gallop",name:"Gallops and chugs",family:"Rhythm",level:"Intermediate",instr:"guitar",summary:"The gallop is an eighth note followed by two sixteenths, usually played on palm-muted power chords or the open low string. Together with steady downpicked chugs it drives a huge amount of metal rhythm guitar.",how:['Count the gallop as "1 & a, 2 & a": a longer note on the beat, then two quick notes on the "&" and the "a". It sits in sixteenths. The triplet gallop is a separate variation.','Palm-mute the open low E or a power chord and pick the gallop down-down-up: downstrokes on the beat and the "&", an upstroke on the "a".','Flip it for the reverse gallop: two sixteenths first, then the eighth, counted "1 e &". Picked down-up-down, it keeps your hand in a steady sixteenth motion.',"Build downpicking stamina with eighth-note chugs played with downstrokes only. Use a metronome, start slow, and raise the tempo only when every stroke is even.","When the picking hand tires, loosen your grip and forearm instead of squeezing harder, and rest before it hurts."],mistakes:['Turning the gallop into a triplet: the two short notes get too long and the riff loses its push. Count "1 & a" out loud against the metronome.',"Squeezing the pick harder as the hand tires: tension slows you down. Relax the grip and keep the motion small.","Raising the tempo before it is clean: uneven strokes become a habit. Move the metronome up a few BPM only after a clean minute.","Playing through pain: fast downpicking can strain the arm, and Exodus guitarist Gary Holt has spoken about chronic tennis elbow from it. Stop when the forearm aches."],used:'Iron Maiden ("Run to the Hills", "The Trooper"), Metallica ("Master of Puppets", "Disposable Heroes"), Slayer\'s reverse gallop on "Raining Blood", Judas Priest ("Exciter") and Dio ("Holy Diver"). Metallica\'s James Hetfield is known for his downpicked rhythm parts, and Exodus\'s Gary Holt calls him the best downpicker out there.',sources:[{id:"s1",title:"Heavy metal gallop",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Heavy_metal_gallop",kind:"encyclopedia"},{id:"s2",title:"Cram Session: Thrash-Metal Rhythms",author:"Jamie Humphries",site:"Premier Guitar",year:2017,url:"https://www.premierguitar.com/articles/25107-cram-session-thrash-metal-rhythms",kind:"lesson"},{id:"s3",title:"ESP School of Metal Guitar: how to play guitar like Iron Maiden",site:"Guitar World",url:"https://www.guitarworld.com/news/esp-school-of-metal-guitar-how-to-play-guitar-like-iron-maiden",kind:"video"},{id:"s4",title:"\"Even James Hetfield cheats, and he's the best out there\": Exodus's Gary Holt on the one trick everyone uses to cheat at downpicking",author:"Crystal Koe",site:"Guitar.com",year:2023,url:"https://guitar.com/news/music-news/exodus-gary-holt-everyone-cheats-at-downpicking/",kind:"interview"},{id:"s5",title:"Shredmental: Hell-Bent for Rhythm!",author:"Brendon Small",site:"Premier Guitar",year:2014,url:"https://www.premierguitar.com/articles/21830-shredmental-hell-bent-for-rhythm",kind:"lesson"},{id:"s6",title:'"We\'re living with 60-year-old arms now!": Gary Holt says "everybody cheats" when it comes to downpicking',author:"Sam Roche",site:"Guitar.com",year:2025,url:"https://guitar.com/news/music-news/gary-holt-says-everybody-cheats-downpicking/",kind:"interview"}],study:[{title:"Iron Maiden: Tech Session",kind:"course",author:"Jamie Humphries (LickLibrary)",url:"https://www.licklibrary.com/learn/courses/iron-maiden-tech-session",note:"Breaks down the timing and picking of Maiden-style gallops along with palm muting."},{title:"Time To Gallop",kind:"lesson",author:"Ben Higgins (GuitarMasterclass)",url:"https://www.guitarmasterclass.net/ls/Time-To-Gallop",note:"A focused down-down-up gallop drill that builds speed in small steps."},{title:"The Number of the Beast (1982)",kind:"album",author:"Iron Maiden",note:'"Run to the Hills" is the reference gallop for guitar and bass together.'},{title:"Master of Puppets (1986)",kind:"album",author:"Metallica",note:"The benchmark for downpicked chugs and gallops at thrash tempos."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"gallop-downpicked-chugs",title:"Downpicked chugs",instr:"guitar",bpm:120,grid:2,notes:[[0,6,0,1,"pm,D"],[1,6,0,1,"pm,D"],[2,6,0,1,"pm,D"],[3,6,0,1,"pm,D"],[4,6,0,1,"pm,D"],[5,6,0,1,"pm,D"],[6,6,3,1,"D,acc"],[6,5,5,1,"D,acc"],[7,5,0,1,"D,acc"],[7,4,2,1,"D,acc"],[8,6,0,1,"pm,D"],[9,6,0,1,"pm,D"],[10,6,0,1,"pm,D"],[11,6,0,1,"pm,D"],[12,6,0,1,"pm,D"],[13,6,0,1,"pm,D"],[14,5,3,1,"D,acc"],[14,4,5,1,"D,acc"],[15,5,2,1,"D,acc"],[15,4,4,1,"D,acc"]],note:"Downstrokes only. Keep the pick motion small and the palm on the strings for the E, then lift it for the two chords at the end of each bar. Start at 100 BPM if 120 feels tight.",cites:["s2","s4"]},{type:"tab",id:"gallop-forward",title:"Forward gallop",instr:"guitar",bpm:120,grid:4,notes:[[0,6,0,2,"pm,D"],[2,6,0,1,"pm,D"],[3,6,0,1,"pm,U"],[4,6,0,2,"pm,D"],[6,6,0,1,"pm,D"],[7,6,0,1,"pm,U"],[8,6,0,2,"pm,D"],[10,6,0,1,"pm,D"],[11,6,0,1,"pm,U"],[12,6,3,2,"pm,D"],[12,5,5,2,"pm,D"],[14,6,3,1,"pm,D"],[14,5,5,1,"pm,D"],[15,6,3,1,"pm,U"],[15,5,5,1,"pm,U"],[16,6,0,2,"pm,D"],[18,6,0,1,"pm,D"],[19,6,0,1,"pm,U"],[20,6,0,2,"pm,D"],[22,6,0,1,"pm,D"],[23,6,0,1,"pm,U"],[24,5,0,2,"pm,D"],[24,4,2,2,"pm,D"],[26,5,0,1,"pm,D"],[26,4,2,1,"pm,D"],[27,5,0,1,"pm,U"],[27,4,2,1,"pm,U"],[28,5,2,2,"pm,D"],[28,4,4,2,"pm,D"],[30,5,2,1,"pm,D"],[30,4,4,1,"pm,D"],[31,5,2,1,"pm,U"],[31,4,4,1,"pm,U"]],note:"Down-down-up on every gallop. Keep the palm mute on for the whole riff, power chords included, so it reads as one steady gallop.",cites:["s2","s3"]},{type:"tab",id:"gallop-reverse",title:"Reverse gallop and switching back",instr:"guitar",bpm:110,grid:4,notes:[[0,6,0,1,"pm,D"],[1,6,0,1,"pm,U"],[2,6,0,2,"pm,D"],[4,6,0,1,"pm,D"],[5,6,0,1,"pm,U"],[6,6,0,2,"pm,D"],[8,6,0,1,"pm,D"],[9,6,0,1,"pm,U"],[10,6,0,2,"pm,D"],[12,5,3,1,"pm,D"],[12,4,5,1,"pm,D"],[13,5,3,1,"pm,U"],[13,4,5,1,"pm,U"],[14,5,3,2,"pm,D"],[14,4,5,2,"pm,D"],[16,6,0,2,"pm,D"],[18,6,0,1,"pm,D"],[19,6,0,1,"pm,U"],[20,6,0,2,"pm,D"],[22,6,0,1,"pm,D"],[23,6,0,1,"pm,U"],[24,5,2,8,"D,acc"],[24,4,4,8,"D,acc"]],note:"Bar 1 flips the gallop: two short notes, then the long one, picked down-up-down. Bar 2 switches back to the forward gallop and ends on a ringing B5, so you practise changing between the two.",cites:["s1","s2"]}]}),LEARN.technique({id:"funk-strumming",name:"Sixteenth-note funk strumming",family:"Rhythm",level:"Intermediate",instr:"guitar",summary:"Your strumming hand moves in steady sixteenths the whole time, and the fretting hand decides which strokes ring as chords and which become muted scratches. Small chord shapes on the top strings keep the part tight and out of the bass player's way.",how:['Set a slow metronome and strum sixteenths without stopping: down on the beat and the "&", up on the "e" and the "a". On rests the hand keeps moving and simply misses the strings.',"Fret a small three- or four-note shape on the higher strings. Dominant 9th chords such as the E9 shape at the 7th fret are the classic funk voicings.","For the scratch, relax the fretting hand so your fingers rest on the strings without pressing them down. Strums now give a dry click with no pitch.","For an accent, press the chord down on just that stroke and let go straight after, so the stab stays short.","Keep the wrist and forearm loose. The picking hand is the timekeeper, so let it swing evenly like a pendulum."],mistakes:["Stopping the strumming hand on rests: the groove drifts. Keep the motion going and miss the strings instead.","Letting chord stabs ring: funk stabs are short. Release fretting pressure right after the stroke.","Using big six-string grips: they get muddy and clash with the bass. Stay on two to four strings near the top of the neck.","Squeezing the pick and stiffening the arm: the sixteenths turn uneven. Loosen up and play a little quieter."],used:'Jimmy Nolen with James Brown ("Papa\'s Got a Brand New Bag", "Cold Sweat"), credited with the "chicken scratch" sound; Nile Rodgers with Chic ("Le Freak", "Good Times"); Freddie Stone with Sly and the Family Stone; and later players such as Cory Wong.',sources:[{id:"s1",title:"Rhythm Rules: Syncopated 16th-Note Rhythms",author:"Alex Nolan",site:"Premier Guitar",year:2013,url:"https://www.premierguitar.com/rhythm-rules-syncopated-16th-note-rhythms",kind:"lesson"},{id:"s2",title:"Where to Start with Funk Guitar",author:"Luke Bowman",site:"Premier Guitar",year:2023,url:"https://www.premierguitar.com/lessons/rhythm/how-to-play-funk-guitar",kind:"lesson"},{id:"s3",title:"The ABCs of Funk Guitar",author:"Ross Bolton",site:"TrueFire",year:2011,url:"https://blog.truefire.com/?p=5661",kind:"lesson"},{id:"s4",title:"5 Funk Guitarists You Should Know",author:"Oscar Jordan",site:"Premier Guitar",year:2011,url:"https://www.premierguitar.com/artists/5-funk-guitarists-you-should-know",kind:"article"},{id:"s5",title:"Jimmy Nolen",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Jimmy_Nolen",kind:"encyclopedia"},{id:"s6",title:"Nile Rodgers",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Nile_Rodgers",kind:"encyclopedia"}],study:[{title:"Funk Guitar in One Chord Shape or Less",kind:"lesson",author:"Shawn Persinger (Premier Guitar)",url:"https://www.premierguitar.com/funk-guitar-in-one-chord-shape-or-less",note:"Gets a lot of funk out of a single small shape, with choked and muted strums."},{title:"6 Funk Guitar Rhythms You MUST Know",kind:"lesson",author:"Chris Buono (TrueFire)",url:"https://blog.truefire.com/guitar-lessons/6-free-funk-rhythm-guitar-lessons/",note:"Short rhythm studies mixing dyads, m9 shapes and single notes."},{title:"Le Freak: An Upside Down Story of Family, Disco, and Destiny",kind:"book",author:"Nile Rodgers",note:'Rodgers describes his own sixteenth-note "chucking" approach in his own words.'},{title:"Nile Rodgers Put Rhythm Up Front (and Cory Wong Listened)",kind:"podcast",author:"Premier Guitar 100 Guitarists",url:"https://www.premierguitar.com/podcast/100-guitarists/nile-rodgers-cory-wong",note:"A modern funk player explains what he took from Rodgers' voicings and right hand."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"funk-strumming-scratch",title:"E9 stabs and scratches",instr:"guitar",bpm:88,grid:4,notes:[[0,4,6,1,"D,acc"],[0,3,7,1,"D,acc"],[0,2,7,1,"D,acc"],[1,4,6,1,"x,U"],[1,3,7,1,"x,U"],[1,2,7,1,"x,U"],[2,4,6,1,"x,D"],[2,3,7,1,"x,D"],[2,2,7,1,"x,D"],[3,4,6,1,"U,acc"],[3,3,7,1,"U,acc"],[3,2,7,1,"U,acc"],[4,4,6,1,"x,D"],[4,3,7,1,"x,D"],[4,2,7,1,"x,D"],[5,4,6,1,"x,U"],[5,3,7,1,"x,U"],[5,2,7,1,"x,U"],[6,4,6,1,"D,acc"],[6,3,7,1,"D,acc"],[6,2,7,1,"D,acc"],[7,4,6,1,"x,U"],[7,3,7,1,"x,U"],[7,2,7,1,"x,U"],[8,4,6,1,"x,D"],[8,3,7,1,"x,D"],[8,2,7,1,"x,D"],[9,4,6,1,"x,U"],[9,3,7,1,"x,U"],[9,2,7,1,"x,U"],[10,4,6,1,"D,acc"],[10,3,7,1,"D,acc"],[10,2,7,1,"D,acc"],[11,4,6,1,"x,U"],[11,3,7,1,"x,U"],[11,2,7,1,"x,U"],[12,4,6,1,"x,D"],[12,3,7,1,"x,D"],[12,2,7,1,"x,D"],[13,4,6,1,"U,acc"],[13,3,7,1,"U,acc"],[13,2,7,1,"U,acc"],[14,4,6,1,"x,D"],[14,3,7,1,"x,D"],[14,2,7,1,"x,D"],[15,4,6,1,"x,U"],[15,3,7,1,"x,U"],[15,2,7,1,"x,U"],[16,4,6,1,"D,acc"],[16,3,7,1,"D,acc"],[16,2,7,1,"D,acc"],[17,4,6,1,"x,U"],[17,3,7,1,"x,U"],[17,2,7,1,"x,U"],[18,4,6,1,"x,D"],[18,3,7,1,"x,D"],[18,2,7,1,"x,D"],[19,4,6,1,"x,U"],[19,3,7,1,"x,U"],[19,2,7,1,"x,U"],[20,4,6,1,"x,D"],[20,3,7,1,"x,D"],[20,2,7,1,"x,D"],[21,4,6,1,"x,U"],[21,3,7,1,"x,U"],[21,2,7,1,"x,U"],[22,4,6,1,"D,acc"],[22,3,7,1,"D,acc"],[22,2,7,1,"D,acc"],[23,4,6,1,"x,U"],[23,3,7,1,"x,U"],[23,2,7,1,"x,U"],[24,4,6,1,"D,acc"],[24,3,7,1,"D,acc"],[24,2,7,1,"D,acc"],[25,4,6,1,"x,U"],[25,3,7,1,"x,U"],[25,2,7,1,"x,U"],[26,4,6,1,"x,D"],[26,3,7,1,"x,D"],[26,2,7,1,"x,D"],[27,4,6,1,"U,acc"],[27,3,7,1,"U,acc"],[27,2,7,1,"U,acc"],[28,4,6,1,"x,D"],[28,3,7,1,"x,D"],[28,2,7,1,"x,D"],[29,4,6,1,"x,U"],[29,3,7,1,"x,U"],[29,2,7,1,"x,U"],[30,4,6,1,"D,acc"],[30,3,7,1,"D,acc"],[30,2,7,1,"D,acc"],[31,4,6,1,"x,U"],[31,3,7,1,"x,U"],[31,2,7,1,"x,U"]],note:"Every sixteenth is strummed. The accented strokes are fretted chords; everything else is a scratch with the fretting fingers resting on the strings. The shape is the middle of the E9 grip at the 7th fret: G#, D and F#, the 3rd, 7th and 9th.",cites:["s1","s2"]},{type:"tab",id:"funk-strumming-two-chords",title:"Em7 to A9 on three strings",instr:"guitar",bpm:96,grid:4,notes:[[0,3,7,1,"D,acc"],[0,2,8,1,"D,acc"],[0,1,7,1,"D,acc"],[1,3,7,1,"x,U"],[1,2,8,1,"x,U"],[1,1,7,1,"x,U"],[2,3,7,1,"x,D"],[2,2,8,1,"x,D"],[2,1,7,1,"x,D"],[3,3,7,1,"U,acc"],[3,2,8,1,"U,acc"],[3,1,7,1,"U,acc"],[4,3,7,1,"x,D"],[4,2,8,1,"x,D"],[4,1,7,1,"x,D"],[5,3,7,1,"x,U"],[5,2,8,1,"x,U"],[5,1,7,1,"x,U"],[6,3,7,1,"D,acc"],[6,2,8,1,"D,acc"],[6,1,7,1,"D,acc"],[7,3,7,1,"x,U"],[7,2,8,1,"x,U"],[7,1,7,1,"x,U"],[8,3,7,1,"D,acc"],[8,2,8,1,"D,acc"],[8,1,7,1,"D,acc"],[9,3,7,1,"x,U"],[9,2,8,1,"x,U"],[9,1,7,1,"x,U"],[10,3,7,1,"x,D"],[10,2,8,1,"x,D"],[10,1,7,1,"x,D"],[11,3,7,1,"U,acc"],[11,2,8,1,"U,acc"],[11,1,7,1,"U,acc"],[12,3,7,1,"x,D"],[12,2,8,1,"x,D"],[12,1,7,1,"x,D"],[13,3,7,1,"x,U"],[13,2,8,1,"x,U"],[13,1,7,1,"x,U"],[14,3,7,1,"D,acc"],[14,2,8,1,"D,acc"],[14,1,7,1,"D,acc"],[15,3,7,1,"x,U"],[15,2,8,1,"x,U"],[15,1,7,1,"x,U"],[16,3,6,1,"D,acc"],[16,2,8,1,"D,acc"],[16,1,7,1,"D,acc"],[17,3,6,1,"x,U"],[17,2,8,1,"x,U"],[17,1,7,1,"x,U"],[18,3,6,1,"D,acc"],[18,2,8,1,"D,acc"],[18,1,7,1,"D,acc"],[19,3,6,1,"x,U"],[19,2,8,1,"x,U"],[19,1,7,1,"x,U"],[20,3,6,1,"x,D"],[20,2,8,1,"x,D"],[20,1,7,1,"x,D"],[21,3,6,1,"x,U"],[21,2,8,1,"x,U"],[21,1,7,1,"x,U"],[22,3,6,1,"D,acc"],[22,2,8,1,"D,acc"],[22,1,7,1,"D,acc"],[23,3,6,1,"x,U"],[23,2,8,1,"x,U"],[23,1,7,1,"x,U"],[24,3,6,1,"x,D"],[24,2,8,1,"x,D"],[24,1,7,1,"x,D"],[25,3,6,1,"x,U"],[25,2,8,1,"x,U"],[25,1,7,1,"x,U"],[26,3,6,1,"D,acc"],[26,2,8,1,"D,acc"],[26,1,7,1,"D,acc"],[27,3,6,1,"x,U"],[27,2,8,1,"x,U"],[27,1,7,1,"x,U"],[28,3,6,1,"D,acc"],[28,2,8,1,"D,acc"],[28,1,7,1,"D,acc"],[29,3,6,1,"x,U"],[29,2,8,1,"x,U"],[29,1,7,1,"x,U"],[30,3,6,1,"x,D"],[30,2,8,1,"x,D"],[30,1,7,1,"x,D"],[31,3,6,1,"U,acc"],[31,2,8,1,"U,acc"],[31,1,7,1,"U,acc"]],note:"Only one note changes between the chords: the G string drops a fret. Small shapes like these keep the scratches tight and leave room for the bass.",cites:["s3","s4"]},{type:"tab",id:"funk-strumming-slide",title:"Sliding into E9",instr:"guitar",bpm:100,grid:4,notes:[[0,4,6,1,"D,acc"],[0,3,7,1,"D,acc"],[0,2,7,1,"D,acc"],[1,4,6,1,"x,U"],[1,3,7,1,"x,U"],[1,2,7,1,"x,U"],[2,4,6,1,"x,D"],[2,3,7,1,"x,D"],[2,2,7,1,"x,D"],[3,4,6,1,"U,acc"],[3,3,7,1,"U,acc"],[3,2,7,1,"U,acc"],[4,4,6,1,"x,D"],[4,3,7,1,"x,D"],[4,2,7,1,"x,D"],[5,4,6,1,"x,U"],[5,3,7,1,"x,U"],[5,2,7,1,"x,U"],[6,4,5,1,"D"],[6,3,6,1,"D"],[6,2,6,1,"D"],[7,4,6,1,"s,U,acc"],[7,3,7,1,"s,U,acc"],[7,2,7,1,"s,U,acc"],[8,4,6,1,"x,D"],[8,3,7,1,"x,D"],[8,2,7,1,"x,D"],[9,4,6,1,"x,U"],[9,3,7,1,"x,U"],[9,2,7,1,"x,U"],[10,4,6,1,"D,acc"],[10,3,7,1,"D,acc"],[10,2,7,1,"D,acc"],[11,4,6,1,"x,U"],[11,3,7,1,"x,U"],[11,2,7,1,"x,U"],[12,4,6,1,"x,D"],[12,3,7,1,"x,D"],[12,2,7,1,"x,D"],[13,4,6,1,"U,acc"],[13,3,7,1,"U,acc"],[13,2,7,1,"U,acc"],[14,4,6,1,"x,D"],[14,3,7,1,"x,D"],[14,2,7,1,"x,D"],[15,4,6,1,"x,U"],[15,3,7,1,"x,U"],[15,2,7,1,"x,U"],[16,4,6,1,"D,acc"],[16,3,7,1,"D,acc"],[16,2,7,1,"D,acc"],[17,4,6,1,"x,U"],[17,3,7,1,"x,U"],[17,2,7,1,"x,U"],[18,4,6,1,"x,D"],[18,3,7,1,"x,D"],[18,2,7,1,"x,D"],[19,4,6,1,"U,acc"],[19,3,7,1,"U,acc"],[19,2,7,1,"U,acc"],[20,4,6,1,"x,D"],[20,3,7,1,"x,D"],[20,2,7,1,"x,D"],[21,4,6,1,"x,U"],[21,3,7,1,"x,U"],[21,2,7,1,"x,U"],[22,4,5,1,"D"],[22,3,6,1,"D"],[22,2,6,1,"D"],[23,4,6,1,"s,U,acc"],[23,3,7,1,"s,U,acc"],[23,2,7,1,"s,U,acc"],[24,4,6,1,"x,D"],[24,3,7,1,"x,D"],[24,2,7,1,"x,D"],[25,4,6,1,"x,U"],[25,3,7,1,"x,U"],[25,2,7,1,"x,U"],[26,4,6,1,"D,acc"],[26,3,7,1,"D,acc"],[26,2,7,1,"D,acc"],[27,4,6,1,"x,U"],[27,3,7,1,"x,U"],[27,2,7,1,"x,U"],[28,4,6,1,"x,D"],[28,3,7,1,"x,D"],[28,2,7,1,"x,D"],[29,4,6,1,"U,acc"],[29,3,7,1,"U,acc"],[29,2,7,1,"U,acc"],[30,4,6,1,"x,D"],[30,3,7,1,"x,D"],[30,2,7,1,"x,D"],[31,4,6,1,"x,U"],[31,3,7,1,"x,U"],[31,2,7,1,"x,U"]],note:'On the "&" of beat 2, fret the shape one fret low and slide it up into E9 on the next upstroke. Sliding dominant 9th chords were part of Freddie Stone\'s playing with Sly and the Family Stone.',cites:["s4"]}]}),LEARN.technique({id:"hybrid-picking",name:"Hybrid and chicken picking",family:"Rhythm",level:"Intermediate",instr:"guitar",summary:'Hold the pick as usual and use your free middle and ring fingers to pluck the higher strings, on their own or together with the pick. In country, rockabilly and bluegrass this hybrid approach is often called "chicken pickin\'".',how:["Hold the pick between thumb and index finger as normal. Let the middle and ring fingers hang curled just above the top strings, ready to pluck.","Share the work: the pick usually takes the bass notes on the lower strings, and the middle and ring fingers take the two highest strings.","Start with pinches: pick a bass note and pluck a higher string with a finger at the same moment. This lets you sound strings far apart, such as the 6th and the 2nd, with no jump.","Then roll through the strings one at a time, pick, middle, ring. Brent Mason uses this kind of pick-and-fingers roll for arpeggios, with a thumbpick in place of the flat pick.","For the chicken-pickin' sound, hook the string with your middle finger and snap it for a biting attack, and mix in dead notes: rest a fretting finger lightly on the string so the pick gives a pitchless click.","In the exercises below, keep the pick notes short and dry and pluck the finger notes a little harder, so the two sound clearly different. Some players add the pinky as a third plucking finger."],mistakes:["Moving the whole hand to reach with a finger: the pick loses its place. Keep the fingers hovering near their strings so only the fingertips move.","Finger notes much quieter than pick notes: the line sounds lopsided. Curl the finger firmly through the string.","Using the pick for every string skip: wide jumps are where the fingers save time and accuracy. Give the high note to the middle finger."],used:"Country, rockabilly, honky-tonk and bluegrass guitar. James Burton played with a flat pick plus a fingerpick on his middle finger, Brent Mason combines a thumbpick with his middle and ring fingers, and Albert Lee, Danny Gatton, Brad Paisley and Greg Koch are well-known hybrid and chicken pickers.",sources:[{id:"s1",title:"Hybrid picking",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Hybrid_picking",kind:"encyclopedia"},{id:"s2",title:"Twang 101: Why You Should Care About Hybrid Picking",author:"Erik Halbig",site:"Premier Guitar",year:2013,url:"https://www.premierguitar.com/twang-101-why-you-should-care-about-hybrid-picking",kind:"lesson"},{id:"s3",title:"Biography",site:"James Burton (official site)",url:"https://www.james-burton.net/biography/",kind:"article"},{id:"s4",title:"Brent Mason: A Chameleon in Tune Town",author:"Joe Charupakorn",site:"Premier Guitar",year:2012,url:"https://www.premierguitar.com/artists/brent-mason-a-chameleon-in-tune-town",kind:"interview"},{id:"s5",title:"Chicken Pickin' for Rockers",author:"Jeff Jacobson",site:"Premier Guitar",year:2023,url:"https://www.premierguitar.com/lessons/country/chicken-pickin-for-rockers",kind:"lesson"},{id:"s6",title:"5 Steps to Better Hybrid Picking",author:"Andy Gibson",site:"Premier Guitar",year:2025,url:"https://www.premierguitar.com/lessons/country/hybrid-picking-guitar-lesson",kind:"lesson"},{id:"s7",title:"Brad Paisley: Concepts and Techniques",author:"Jeffrey Adams",site:"Premier Guitar",year:2013,url:"https://www.premierguitar.com/artists/brad-paisley-concepts-and-techniques",kind:"lesson"}],study:[{title:"Diversify your playing with Greg Koch's red-hot hybrid-picking lesson",kind:"video",author:"Greg Koch (Guitar World)",url:"https://www.guitarworld.com/lessons/diversify-your-playing-with-greg-kochs-red-hot-hybrid-picking-lesson",note:"Hybrid picking taught by one of its best-known teachers."},{title:"Guitar Technique Encyclopedia",kind:"book",author:"National Guitar Workshop (Alfred, 2001)",url:"https://books.google.com/books?id=zFgVl1E6r_EC&pg=PA117",note:"A broad technique reference with a clear section on hybrid picking."},{title:"Essential Rock Guitar Techniques",kind:"book",author:"Chad Johnson (Hal Leonard, 2012)",url:"https://books.google.com/books?id=82rxCQAAQBAJ&dq=%22hybrid+picking%22&pg=PT89",note:"Shows how rock players use the same pick-and-fingers approach."},{title:"Play (2008)",kind:"album",author:"Brad Paisley",note:'Includes "Cluster Pluck", a Grammy-winning guitar instrumental featuring Brent Mason among other country pickers.'}],cites:["s1","s2","s3","s4","s5","s6","s7"],blocks:[{type:"tab",id:"hybrid-picking-pinches",title:"Bass and finger pinches",instr:"guitar",bpm:100,grid:2,notes:[[0,6,3,1,"pm,D"],[1,2,0,1,"M"],[1,1,3,1,"A"],[2,4,0,1,"pm,D"],[3,2,0,1,"M"],[3,1,3,1,"A"],[4,6,3,1,"pm,D"],[5,2,0,1,"M"],[5,1,3,1,"A"],[6,4,0,1,"pm,D"],[7,2,0,1,"M"],[7,1,3,1,"A"],[8,5,3,1,"pm,D"],[9,2,1,1,"M"],[9,1,0,1,"A"],[10,6,3,1,"pm,D"],[11,2,1,1,"M"],[11,1,0,1,"A"],[12,5,3,1,"pm,D"],[13,2,1,1,"M"],[13,1,0,1,"A"],[14,6,3,1,"pm,D"],[15,2,1,1,"M"],[15,1,0,1,"A"]],note:'The pick plays the bass on every beat with a light palm mute; the middle and ring fingers pluck the top two strings together on every "&". On C, move your ring finger between the 5th and 6th strings for the bass.',cites:["s1","s6"]},{type:"tab",id:"hybrid-picking-rolls",title:"Pick, middle, ring rolls",instr:"guitar",bpm:80,grid:4,ring:!0,notes:[[0,5,0,3,"D"],[1,2,2,2,"M"],[2,1,0,2,"A"],[3,4,2,3,"D"],[4,2,2,2,"M"],[5,1,0,2,"A"],[6,5,0,3,"D"],[7,2,2,2,"M"],[8,1,0,2,"A"],[9,4,2,3,"D"],[10,2,2,2,"M"],[11,1,0,2,"A"],[12,5,0,3,"D"],[13,2,2,2,"M"],[14,1,0,2,"A"],[15,4,2,3,"D"],[16,4,0,3,"D"],[17,2,3,2,"M"],[18,1,2,2,"A"],[19,3,2,3,"D"],[20,2,3,2,"M"],[21,1,2,2,"A"],[22,4,0,3,"D"],[23,2,3,2,"M"],[24,1,0,2,"A"],[25,4,2,3,"D"],[26,2,0,2,"M"],[27,1,0,2,"A"],[28,6,0,3,"D"],[29,2,0,2,"M"],[30,1,0,2,"A"],[31,4,2,3,"D"]],note:"A pick-middle-ring roll in groups of three against a four-beat bar, so the accent keeps shifting. Chords: A, then D and E. Let every note ring.",cites:["s4"]},{type:"tab",id:"hybrid-picking-chicken",title:"Chicken-pickin' lick over A7",instr:"guitar",bpm:84,grid:4,notes:[[0,3,2,1,"D,x"],[1,2,2,1,"M,acc"],[2,3,2,1,"D,x"],[3,2,5,1,"M,acc"],[4,3,4,1,"D,pm"],[5,2,5,1,"M,acc"],[6,3,6,1,"D,pm"],[7,2,8,1,"M,acc"],[8,2,5,2,"M,acc"],[8,1,5,2,"A,acc"],[10,3,6,1,"D,pm"],[11,2,5,1,"M,acc"],[12,3,5,1,"D"],[13,3,6,1,"h"],[14,3,2,2,"D,pm"],[16,5,0,8,"D"],[16,2,2,8,"M"],[16,1,2,8,"A,v"]],note:"Pick notes are either dead clicks (x) or palm-muted, and finger notes are plucked harder. Beat 4 hammers from C to C#, the minor to the major third of A7, and the lick ends on an A6 pinch.",cites:["s2","s5"]}]}),LEARN.technique({id:"travis-picking",name:"Travis picking",family:"Fingerstyle",level:"Intermediate",instr:"guitar",summary:"Your thumb keeps a steady alternating bass on every beat while the index and middle fingers add melody and chord notes on top, on and between the beats. The style is named after Merle Travis and was developed further by Chet Atkins.",how:["Start with the thumb alone. On a C chord play the 5th, 4th, 6th and 4th strings as steady quarter notes; on G or any 6th-string root use the 6th, 4th, 5th and 4th.","Rest the edge of your picking hand lightly on the bass strings just in front of the bridge. The light damping makes the thumb short and clicky, which is part of the sound.",'Add the index and middle fingers on the 2nd and 1st strings between the thumb notes, on each "&". The thumb never changes what it is doing.',"Add pinches: thumb and a finger plucking together on the beat, often to start a phrase.",'Syncopate the melody by playing a finger note on the "&" just before a beat and letting it ring over the next thumb note.',"A thumbpick gives the bass more punch, and Merle Travis played with one, but a bare thumb works fine for practice."],mistakes:["The thumb stops or follows the fingers: the groove falls apart. Drill the bass alone until it runs on autopilot, then add one finger note at a time.","A boomy, undamped bass that drowns the melody: rest the edge of the hand on the bass strings near the bridge.",'Adding syncopation too early: get the straight version, fingers on every "&", steady at a slow tempo first.'],used:"Country and folk fingerpicking: Merle Travis, Chet Atkins, Doc Watson, Jerry Reed and Tommy Emmanuel, and singer-songwriters such as James Taylor and John Prine. Mississippi John Hurt is among the early players of the style on record.",sources:[{id:"s1",title:"Twang 101: Travis Picking Essentials",author:"Tom Monda",site:"Premier Guitar",year:2013,url:"https://www.premierguitar.com/twang-101-travis-picking-essentials",kind:"lesson"},{id:"s2",title:"One Note at a Time: A Chet Atkins Primer",author:"Sean Weaver",site:"Premier Guitar",year:2024,url:"https://www.premierguitar.com/lessons/one-note-at-a-time-a-chet-atkins-primer",kind:"lesson"},{id:"s3",title:"Acoustic Bootcamp: Travis Picking",author:"Brooks Robertson",site:"TrueFire",url:"https://truefire.com/c1604",kind:"lesson"},{id:"s4",title:"Mutant Folk Fingerpicking",author:"Joe Gore",site:"Premier Guitar",year:2020,url:"https://www.premierguitar.com/lessons/mutant-folk-fingerpicking?rebelltitem=6",kind:"lesson"},{id:"s5",title:"Travis picking",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Travis_picking",kind:"encyclopedia"},{id:"s6",title:"Merle Travis",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Merle_Travis",kind:"encyclopedia"}],study:[{title:"Fingerstyle Guitar: Travis Picking",kind:"video",author:"Stevie Coyle (Peghead Nation)",url:"https://www.pegheadnation.com/string-school/courses/fingerstyle-guitar/travis-picking/",note:"Builds from alternating bass to a pinch pattern to palm muting, one step at a time."},{title:"Merle's Thumb (Lesson 18)",kind:"video",author:"Andy Guitar",url:"https://www.andyguitar.co.uk/videos/lesson-18-merles-thumb",note:"Thumb-only drills with muted bass strings, the part most players rush past."},{title:"Folk Songs of the Hills (1947)",kind:"album",author:"Merle Travis",note:'The source recordings of the style, including "Sixteen Tons" and "Dark as a Dungeon".'},{title:"Acoustic Bootcamp: Travis Picking",kind:"course",author:"Brooks Robertson (TrueFire)",url:"https://truefire.com/c1604",note:"A structured course on 6th-, 5th- and 4th-string bass patterns, muting and thumbpick setup."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"travis-picking-basic",title:'Thumb on the beat, fingers on the "&"',instr:"guitar",bpm:90,grid:2,ring:!0,notes:[[0,5,3,2,"P,pm"],[1,2,1,3,"I"],[2,4,2,2,"P,pm"],[3,1,0,3,"M"],[4,6,3,2,"P,pm"],[5,2,1,3,"I"],[6,4,2,2,"P,pm"],[7,1,0,3,"M"],[8,6,3,2,"P,pm"],[9,2,0,3,"I"],[10,4,0,2,"P,pm"],[11,1,3,3,"M"],[12,5,2,2,"P,pm"],[13,2,0,3,"I"],[14,4,0,2,"P,pm"],[15,1,3,3,"M"]],note:'C then G. The thumb alternates bass strings on every beat with a light palm mute, and the fingers fill every "&". On C your ring finger moves between the 5th and 6th strings.',cites:["s1","s2"]},{type:"tab",id:"travis-picking-pinch",title:"Pinches and a syncopated melody",instr:"guitar",bpm:90,grid:2,ring:!0,notes:[[0,5,3,2,"P,pm"],[0,1,0,3,"M"],[1,2,1,3,"I"],[2,4,2,2,"P,pm"],[3,1,3,4,"M"],[4,6,3,2,"P,pm"],[5,2,1,3,"I"],[6,4,2,2,"P,pm"],[7,1,0,3,"M"],[8,6,3,2,"P,pm"],[8,1,1,3,"M"],[9,2,0,3,"I"],[10,4,0,2,"P,pm"],[11,2,3,4,"I"],[12,5,2,2,"P,pm"],[13,2,0,3,"I"],[14,4,0,2,"P,pm"],[15,1,1,3,"M"]],note:'C then G7. Beat 1 of each bar is a pinch, and the finger note on the "&" of 2 is held over beat 3, which gives the style its lilt. The thumb part is exactly the same as in the first exercise.',cites:["s1","s4"]},{type:"tab",id:"travis-picking-progression",title:"Four-bar progression with melody",instr:"guitar",bpm:96,grid:2,ring:!0,notes:[[0,5,3,2,"P,pm"],[0,1,0,3,"M"],[1,2,1,3,"I"],[2,4,2,2,"P,pm"],[3,1,3,4,"M"],[4,6,3,2,"P,pm"],[5,2,1,3,"I"],[6,4,2,2,"P,pm"],[7,1,0,3,"M"],[8,5,0,2,"P,pm"],[8,2,1,3,"M"],[9,3,2,3,"I"],[10,4,2,2,"P,pm"],[11,1,0,4,"M"],[12,6,0,2,"P,pm"],[13,2,1,3,"I"],[14,4,2,2,"P,pm"],[15,1,0,3,"M"],[16,4,3,2,"P,pm"],[16,1,0,3,"M"],[17,2,1,3,"I"],[18,3,2,2,"P,pm"],[19,1,1,4,"M"],[20,5,3,2,"P,pm"],[21,2,1,3,"I"],[22,3,2,2,"P,pm"],[23,1,0,3,"M"],[24,6,3,2,"P,pm"],[24,1,1,3,"M"],[25,2,0,3,"I"],[26,4,0,2,"P,pm"],[27,2,3,4,"I"],[28,5,2,2,"P,pm"],[29,2,0,3,"I"],[30,4,0,2,"P,pm"],[31,1,1,3,"M"]],note:"C, Am, Fmaj7 (x33210) and G7, with a pinch at the start of each bar and one syncopated melody note per bar. On Fmaj7 the thumb moves between the 4th, 3rd and 5th strings."}]}),LEARN.technique({id:"fingerstyle-pima",name:"Classical fingerstyle (p-i-m-a)",family:"Fingerstyle",level:"Beginner",instr:"guitar",summary:"Classical guitarists name the picking-hand fingers p, i, m and a and give each one a job: the thumb takes the bass strings and the fingers take the treble strings. Two strokes cover most of the music: free stroke for arpeggios and chords, rest stroke for melody.",how:["Learn the names: p, i, m and a stand for pulgar, índice, medio and anular (thumb, index, middle, ring). The thumb plays the bass strings, and i, m and a usually take three neighbouring treble strings.","Free stroke (tirando): the finger plucks and moves past without touching the next string, so everything keeps ringing. Use it for arpeggios and chords.","Begin each free stroke with the fingertip resting on the string, then shorten that preparation as you get comfortable so the notes connect smoothly.","Rest stroke (apoyando): the finger pushes through and comes to rest on the next string. It gives a fuller, louder note for melodies and scales, but it stops that next string from ringing.","Drill arpeggio patterns such as p-i-m-a and p-a-m-i on simple chords. Mauro Giuliani's 120 right-hand studies (Op. 1) are the classic workout for this.","Tone comes from nail and flesh together. Keep the nail edge smooth and polished, since a rough edge sounds scratchy."],mistakes:["Using rest stroke inside an arpeggio: the finger lands on the next string and cuts it off. Arpeggios use free stroke.","Rough or uneven nails: the notes sound scratchy and inconsistent. Smooth the edge with fine paper; no single nail shape suits everyone.","Letting the thumb wander onto the treble strings: keep p on the bass and each finger on its own string, so the hand barely moves."],used:"Classical and nylon-string guitar: the studies of Mauro Giuliani, Romantic pieces by Francisco Tárrega, and the concert tradition popularised by Andrés Segovia.",sources:[{id:"s1",title:"Classical guitar technique",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Classical_guitar_technique",kind:"encyclopedia"},{id:"s2",title:"Rest Stroke Technique on the Classical Guitar",author:"Simon Powis",site:"Classical Guitar Corner",year:2014,url:"https://www.classicalguitarcorner.com/l111-rest-stroke-on-the-classical-guitar/",kind:"lesson"},{id:"s3",title:"Free Stroke Technique",author:"Simon Powis",site:"Classical Guitar Corner",year:2014,url:"https://www.classicalguitarcorner.com/free-stroke-on-the-classical-guitar/",kind:"lesson"},{id:"s4",title:"Why You Should Avoid Rest Strokes on Classical Guitar (for now)",author:"Allen Mathews",site:"Classical Guitar Shed",url:"https://classicalguitarshed.com/rest-strokes/",kind:"lesson"},{id:"s5",title:"Lesson: Use Giuliani's 'Studies' to Increase Right-Hand Development",author:"Adam Perlmutter",site:"Classical Guitar Magazine",year:2010,url:"https://classicalguitarmagazine.com/lesson-use-giulianis-studies-to-increase-right-hand-development/",kind:"lesson"},{id:"s6",title:"Learn the Essential Techniques of Fingerstyle Acoustic Guitar",author:"Doug Young",site:"Acoustic Guitar",year:2022,url:"https://acousticguitar.com/learn-fingerstyle-acoustic-guitar-essentials/",kind:"lesson"},{id:"s7",title:"Classical Guitar Fingernails",author:"Dave Belcher",site:"Classical Guitar Corner",year:2022,url:"https://www.classicalguitarcorner.com/nails-on-classical-guitar/",kind:"lesson"}],study:[{title:"120 Right Hand Studies (Op. 1, Part One)",kind:"book",author:"Mauro Giuliani",url:"https://www.thisisclassicalguitar.com/giuliani-120-arpeggio-studies-op-1/",note:"The standard p-i-m-a arpeggio workout for finger independence, still used in early training. Bradford Werner offers Nos. 1 to 20 as a free PDF."},{title:"Classical Guitar Corner courses",kind:"course",author:"Simon Powis",url:"https://www.classicalguitarcorner.com/join-cgc/",note:"A graded course from the authors of the rest-stroke and free-stroke lessons above."},{title:"Q&A Lesson: Rest and Free Stroke on Classical Guitar",kind:"video",author:"Bradford Werner (This Is Classical Guitar)",url:"https://www.thisisclassicalguitar.com/lesson-rest-free-stroke-on-classical-guitar/",note:"A practical routine for practising both strokes."},{title:"Pumping Nylon",kind:"book",author:"Scott Tennant",note:"A widely used technique book for the classical right hand."}],cites:["s1","s2","s3","s4","s5","s6","s7"],blocks:[{type:"tab",id:"fingerstyle-pima-arpeggio",title:"p-i-m-a arpeggio: Am to E7",instr:"guitar",bpm:66,grid:4,ring:!0,notes:[[0,5,0,4,"P"],[1,3,2,3,"I"],[2,2,1,2,"M"],[3,1,0,1,"A"],[4,4,2,4,"P"],[5,3,2,3,"I"],[6,2,1,2,"M"],[7,1,0,1,"A"],[8,5,0,4,"P"],[9,3,2,3,"I"],[10,2,1,2,"M"],[11,1,0,1,"A"],[12,4,2,4,"P"],[13,3,2,3,"I"],[14,2,1,2,"M"],[15,1,0,1,"A"],[16,6,0,4,"P"],[17,3,1,3,"I"],[18,2,0,2,"M"],[19,1,0,1,"A"],[20,5,2,4,"P"],[21,3,1,3,"I"],[22,2,0,2,"M"],[23,1,0,1,"A"],[24,6,0,4,"P"],[25,3,1,3,"I"],[26,2,0,2,"M"],[27,1,0,1,"A"],[28,5,2,4,"P"],[29,3,1,3,"I"],[30,2,0,2,"M"],[31,1,0,1,"A"]],note:"Ideally on a nylon-string guitar. Free strokes throughout, one finger per string: p on the bass, i on the 3rd string, m on the 2nd, a on the 1st. Aim for four equal volumes and let everything ring.",cites:["s1","s3"]},{type:"tab",id:"fingerstyle-pima-triplets",title:"Up-and-back arpeggios in triplets",instr:"guitar",bpm:72,grid:3,ring:!0,notes:[[0,5,3,6,"P"],[1,3,0,3,"I"],[2,2,1,3,"M"],[3,1,0,3,"A"],[4,2,1,3,"M"],[5,3,0,3,"I"],[6,6,3,6,"P"],[7,3,0,3,"I"],[8,2,1,3,"M"],[9,1,0,3,"A"],[10,2,1,3,"M"],[11,3,0,3,"I"],[12,5,0,6,"P"],[13,3,2,3,"I"],[14,2,1,3,"M"],[15,1,0,3,"A"],[16,2,1,3,"M"],[17,3,2,3,"I"],[18,6,0,6,"P"],[19,3,2,3,"I"],[20,2,1,3,"M"],[21,1,0,3,"A"],[22,2,1,3,"M"],[23,3,2,3,"I"],[24,4,0,6,"P"],[25,1,1,3,"A"],[26,2,3,3,"M"],[27,3,2,3,"I"],[28,2,3,3,"M"],[29,1,1,3,"A"],[30,5,0,6,"P"],[31,1,1,3,"A"],[32,2,3,3,"M"],[33,3,2,3,"I"],[34,2,3,3,"M"],[35,1,1,3,"A"],[36,6,3,6,"P"],[37,1,1,3,"A"],[38,2,0,3,"M"],[39,3,0,3,"I"],[40,2,0,3,"M"],[41,1,1,3,"A"],[42,5,2,6,"P"],[43,1,1,3,"A"],[44,2,0,3,"M"],[45,3,0,3,"I"],[46,2,0,3,"M"],[47,1,1,3,"A"]],note:"C, Am, Dm, G7. Bars 1 and 2 use p-i-m-a-m-i, bars 3 and 4 the reverse p-a-m-i-m-a. On nylon strings, keep every stroke a free stroke so the chord rings.",cites:["s1","s6"]},{type:"tab",id:"fingerstyle-pima-rest-stroke",title:"Rest-stroke melody over a free-stroke bass",instr:"guitar",bpm:76,grid:2,ring:!0,notes:[[0,5,0,4,"P"],[4,4,2,4,"P"],[8,6,0,4,"P"],[12,5,0,4,"P"],[0,3,2,1,"I,acc"],[1,2,1,1,"M,acc"],[2,1,0,1,"I,acc"],[3,1,5,1,"M,acc"],[4,1,3,1,"I,acc"],[5,1,0,1,"M,acc"],[6,1,1,1,"I,acc"],[7,2,3,1,"M,acc"],[8,2,0,1,"I,acc"],[9,2,3,1,"M,acc"],[10,2,1,1,"I,acc"],[11,2,0,1,"M,acc"],[12,3,2,4,"I,acc"]],note:"Play the melody with alternating i and m rest strokes (the accented notes) and the bass with free strokes from the thumb. On a nylon-string guitar the rest stroke makes the tune sing out over the bass.",cites:["s2","s4"]}]}),LEARN.technique({id:"open-tunings",name:"Open and alternate tunings",family:"Tuning",level:"Intermediate",instr:"guitar",summary:"An open tuning sets the strings so that strumming them open gives a chord, and one finger laid across a single fret gives other major chords. Open G, Open D, DADGAD and Open E or A each bring their own drones, shapes and sound.",how:["Retune one string at a time with a tuner. From standard, Open G (D G D G B D) lowers the 6th, 5th and 1st strings a whole step. Open D is D A D F# A D and DADGAD is D A D G A D.","Strum the open strings to hear the home chord, then lay one finger flat across a fret. In Open G a barre at the 5th fret gives C and at the 7th gives D.","Learn a couple of shapes that move against the open strings, then move them up with the barre. Keith Richards plays Open G on a five-string guitar with the low string removed, so the root of the chord sits on the bottom.",'Use the open strings as drones. DADGAD\'s open chord is a Dsus4, neither major nor minor, and its drones suit the Celtic and folk music it is linked with; it is sometimes called the "Celtic tuning".',"Open E (E B E G# B E) and Open A (E A E A C# E) have the same intervals as Open D and Open G, a whole step higher. Tuning up adds string tension, so many players capo Open D at the 2nd fret instead of tuning to Open E (the same trick turns Open G into Open A), or use light strings."],mistakes:["Tuning strings up too far or too fast: the extra tension can snap them. Tune down to Open D or G and use a capo for the higher keys.","Fretting standard-tuning chord shapes: they sound wrong in a new tuning. Start from the open chord and one-finger barres, then find new shapes by ear.","Strumming every string on every chord: in Open G the low D sits under all chords and can muddy them. Try leaving the 6th string out, the way five-string players do."],used:'Keith Richards in Open G ("Brown Sugar", "Honky Tonk Women", "Start Me Up"), Joni Mitchell in Open D ("Big Yellow Taxi") and many other tunings, Jimmy Page in DADGAD ("Kashmir"), Davy Graham and Pierre Bensusan in DADGAD, and Elmore James, Duane Allman and Derek Trucks playing slide in Open E.',sources:[{id:"s1",title:"List of guitar tunings",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/List_of_guitar_tunings",kind:"encyclopedia"},{id:"s2",title:"Get Started Playing in Open Tunings: Right Now!",author:"Ted Drozdowski",site:"Gibson",year:2011,url:"https://legacy.gibson.com/News-Lifestyle/Features/en-us/open-tuning-0902-2011.aspx",kind:"lesson"},{id:"s3",title:"Digging Deeper: Open-G Tricks",author:"Shawn Persinger",site:"Premier Guitar",year:2015,url:"https://www.premierguitar.com/digging-deeper-open-g-tricks",kind:"lesson"},{id:"s4",title:"Keith Richards Demonstrates His Famous 5-String Technique",author:"Josh Jones",site:"Open Culture",year:2021,url:"https://www.openculture.com/2021/05/keith-richards-demonstrates-his-famous-5-string-technique.html",kind:"interview"},{id:"s5",title:"DADGAD Chords: Modal Tuning Favored by Fingerstyle Players",author:"TrueFire Education Team",site:"TrueFire",year:2026,url:"https://blog.truefire.com/guitar-lessons/dadgad-chords-modal-tuning-celtic-fingerstyle/",kind:"lesson"},{id:"s6",title:"Open E tuning",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Open_E_tuning",kind:"encyclopedia"},{id:"s7",title:"Interview: Pierre Bensusan",author:"Adam Perlmutter",site:"Premier Guitar",year:2011,url:"https://www.premierguitar.com/interview-pierre-bensusan",kind:"interview"},{id:"s8",title:"Keith Richards: Rhythm of a Rolling Stone, Part 1",author:"Joe Deloro",site:"TrueFire",year:2011,url:"https://blog.truefire.com/guitar-lessons/keith-richards-rhythm-rolling-stones-part-1/",kind:"lesson"}],study:[{title:"Blue (1971)",kind:"album",author:"Joni Mitchell",url:"https://en.wikipedia.org/wiki/Blue_(Joni_Mitchell_album)",note:"A whole album of songs shaped by open and alternate tunings."},{title:"What's the Deal With DADGAD Tuning?",kind:"article",author:"Stringjoy",url:"https://stringjoy.com/whats-deal-dadgad-tuning/",note:"A short, practical introduction to DADGAD drones and shapes."},{title:"The Guitar Book (1985)",kind:"book",author:"Pierre Bensusan",note:"DADGAD method and pieces from the tuning's best-known player."},{title:"She Moved Through the Fair (live, 1964)",kind:"album",author:"Davy Graham",note:"An early DADGAD recording that influenced Jimmy Page and a generation of folk players."}],cites:["s1","s2","s3","s4","s5","s6","s7","s8"],blocks:[{type:"tuning",name:"Open G",notes:"D2 G2 D3 G3 B3 D4",note:"From standard, lower the 6th, 5th and 1st strings a whole step. Strummed open, it is a G major chord.",cites:["s3"]},{type:"tuning",name:"Open D",notes:"D2 A2 D3 F#3 A3 D4",note:"From standard, lower the 6th, 2nd and 1st strings a whole step and the 3rd string a half step.",cites:["s1","s2"]},{type:"tuning",name:"DADGAD",notes:"D2 A2 D3 G3 A3 D4",note:"From standard, lower the 6th, 2nd and 1st strings a whole step. The open strings form a Dsus4 chord.",cites:["s1","s7"]},{type:"tuning",name:"Open E",notes:"E2 B2 E3 G#3 B3 E4",note:"Open D a whole step up: raise the 5th and 4th strings a whole step and the 3rd a half step. Capo Open D at the 2nd fret for the same sound with less tension.",cites:["s1","s6"]},{type:"tuning",name:"Open A (slide)",notes:"E2 A2 E3 A3 C#4 E4",note:"Open G a whole step up, a common slide tuning. Some lists give E A C# E A E under the same name.",cites:["s1"]},{type:"shapes",title:"Open G shapes",tuning:"D2 G2 D3 G3 B3 D4",shapes:[{name:"G",frets:"0 0 0 0 0 0"},{name:"C6/9 over G",frets:"x 0 2 2 1 0"},{name:"C",frets:"5 5 5 5 5 5"},{name:"D",frets:"7 7 7 7 7 7"},{name:"Em7",frets:"2 x 2 0 0 0"}],note:"One-finger barres give every major chord. The second shape adds a C chord over the open G bass; move it up with the barre for the same move in other keys.",cites:["s3"]},{type:"shapes",title:"Open D shapes",tuning:"D2 A2 D3 F#3 A3 D4",shapes:[{name:"D",frets:"0 0 0 0 0 0"},{name:"Dsus4",frets:"0 0 0 1 0 0"},{name:"G",frets:"5 5 5 5 5 5"},{name:"A",frets:"7 7 7 7 7 7"}],note:"The same idea in Open D: barre at 5 for the IV chord and at 7 for the V chord. These shapes work in Open E too, two frets higher in pitch.",cites:["s2","s6"]},{type:"shapes",title:"DADGAD shapes",tuning:"D2 A2 D3 G3 A3 D4",shapes:[{name:"Dsus4",frets:"0 0 0 0 0 0"},{name:"D5",frets:"0 0 0 2 0 0"},{name:"G/D",frets:"0 x 0 0 2 0"},{name:"Asus4",frets:"x 0 2 2 0 0"}],note:"Small shapes that leave most strings open, so the drones keep ringing under every chord.",cites:["s5"]},{type:"tab",id:"open-tunings-open-g-riff",title:"Five-string Open G riff",instr:"guitar",tuning:"D2 G2 D3 G3 B3 D4",bpm:104,grid:4,notes:[[0,5,0,2,"D"],[0,4,0,2,"D"],[0,3,0,2,"D"],[0,2,0,2,"D"],[0,1,0,2,"D"],[2,5,0,2,"U"],[2,4,0,2,"U"],[2,3,0,2,"U"],[2,2,0,2,"U"],[2,1,0,2,"U"],[4,5,0,2,"D"],[4,4,0,2,"D"],[4,3,0,2,"D"],[4,2,0,2,"D"],[4,1,0,2,"D"],[6,2,0,1,"D"],[7,2,1,1,"h"],[8,5,0,4,"D"],[8,4,0,4,"D"],[8,3,0,4,"D"],[8,2,0,4,"D"],[8,1,0,4,"D"],[12,5,2,1,"D"],[13,5,4,1,"U"],[14,5,5,1,"D"],[15,5,6,1,"U"],[16,5,7,2,"D"],[16,4,7,2,"D"],[16,3,7,2,"D"],[16,2,7,2,"D"],[16,1,7,2,"D"],[18,5,7,2,"U"],[18,4,7,2,"U"],[18,3,7,2,"U"],[18,2,7,2,"U"],[18,1,7,2,"U"],[20,2,7,1,"D"],[21,2,8,1,"h"],[22,2,7,2,"p"],[24,5,7,2,"D"],[24,4,7,2,"D"],[24,3,7,2,"D"],[24,2,7,2,"D"],[24,1,7,2,"D"],[26,5,7,2,"U"],[26,4,7,2,"U"],[26,3,7,2,"U"],[26,2,7,2,"U"],[26,1,7,2,"U"],[28,5,0,4,"D,acc"],[28,4,0,4,"D,acc"],[28,3,0,4,"D,acc"],[28,2,0,4,"D,acc"],[28,1,0,4,"D,acc"]],note:"Leave the low 6th string silent, as five-string players do. Bar 1 strums the open G chord, adds a hammer-on on the B string and walks the bass up to the 7th fret. Bar 2 barres the 7th fret for D, decorates it with a hammer-on and pull-off, then lands back on open G.",cites:["s3","s4"]},{type:"tab",id:"open-tunings-dadgad-drone",title:"DADGAD melody over drones",instr:"guitar",tuning:"D2 A2 D3 G3 A3 D4",bpm:84,grid:2,ring:!0,notes:[[0,6,0,8,"P"],[0,1,0,4,"A"],[1,3,0,3,"I"],[2,2,0,3,"M"],[3,3,2,3,"I"],[4,1,2,2,"A"],[5,2,0,3,"M"],[6,1,4,4,"A"],[7,3,0,3,"I"],[8,5,0,4,"P"],[8,1,5,3,"A"],[9,3,0,3,"I"],[10,2,0,2,"M"],[11,1,4,1,"A"],[12,6,0,4,"P"],[12,1,2,2,"A"],[13,2,0,3,"M"],[14,1,0,4,"A"],[15,3,0,2,"I"]],note:"Thumb on the low D and A, fingers on the open G and A strings for drones, melody on the 1st string. The open strings ring under every melody note, which is the sound DADGAD is known for.",cites:["s5"]}]}),LEARN.technique({id:"slide-guitar",name:"Bottleneck slide",family:"Lead",level:"Intermediate",instr:"guitar",summary:"A tube of glass, metal or ceramic worn on one finger glides along the strings instead of pressing them to the frets, giving smooth glissandos and a vocal vibrato. Open tunings put a major chord under a straight slide, which is why so many slide players use them.",how:['Pick a slide. Glass is lighter and smoother, steel and brass are heavier with more sustain and a brighter edge, and ceramic sits in between. The name "bottleneck" comes from bottle necks used as slides.',"Wear it on the ring finger or the pinky, the two usual choices. The pinky leaves three fingers free for chords. Avoid the index: it leaves no finger behind the slide to mute with.","For pitch, hold the slide directly over the fret wire. That is further up than normal fretting, where the finger sits just behind the fret. Let it rest on the strings with just enough weight that they do not touch the frets.","Mute behind the slide by letting a finger trail lightly on the strings, and use the picking hand's fingers and palm to damp strings you are not playing. Most slide players pick with their fingers for this reason.","Make vibrato by moving the slide quickly side to side around the fret, the same distance either way.","Tune to Open G, Open D or Open E so a straight slide across one fret gives a major chord. Standard tuning works for single notes but gives fewer chord tones at each fret. Slightly higher action helps the slide clear the frets."],mistakes:["Stopping between the frets: the note comes out flat. Watch the fret wire and stop right above it.","Pressing down: the slide clanks against the frets and buzzes. Rest it on the strings with light weight.","Strings ringing behind the slide: you get a howl of unwanted pitches. Trail a finger behind the slide and mute with the picking hand.","Very low action: the slide hits the frets and the sustain dies. Raise the action a little on a guitar kept for slide."],used:"Delta and Chicago blues (Elmore James in open E, Muddy Waters in open G), Southern rock (Duane Allman, who used a glass medicine bottle), and rock players such as Joe Perry and Billy Gibbons, who use ceramic slides.",sources:[{id:"s1",title:"How to Play Slide Guitar, Part 1",author:"Mike Levine",site:"Yamaha Hub",year:2019,url:"https://hub.yamaha.com/how-to-play-slide-guitar-part-1/",kind:"lesson"},{id:"s2",title:"How to Play Slide Guitar, Part 2",author:"Mike Levine",site:"Yamaha Hub",year:2019,url:"https://hub.yamaha.com/how-to-play-slide-guitar-part-2/",kind:"lesson"},{id:"s3",title:"Slide guitar",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Slide_guitar",kind:"encyclopedia"},{id:"s4",title:"Proper Slide Guitar Technique (from Blues Guitar For Dummies)",author:"Jon Chappell",site:"Dummies",year:2016,url:"https://dummies.com/article/academics-the-arts/music/instruments/guitar/proper-slide-guitar-technique-206620",kind:"book"},{id:"s5",title:"A Beginner's Guide to Standard Slide",author:"Arthur Rotfeld",site:"Premier Guitar",year:2020,url:"https://www.premierguitar.com/lessons/a-beginners-guide-to-standard-slide",kind:"lesson"},{id:"s6",title:"Four different materials for slide on electric guitar",author:"Lewis Noke Edwards",site:"Mixdown",year:2025,url:"https://mixdownmag.com.au/features/four-different-materials-for-slide-on-electric-guitar/",kind:"article"},{id:"s7",title:"Dust That Broom! A Newbie's Guide to Slide",author:"Ted Drozdowski",site:"Premier Guitar",year:2017,url:"https://www.premierguitar.com/diy/dust-that-broom-a-newbies-guide-to-slide",kind:"lesson"},{id:"s8",title:"Duane Allman: Master of Southern Slide",author:"Arlen Roth",site:"TrueFire",year:2011,url:"https://blog.truefire.com/guitar-lessons/duane-allman-southern-slide/",kind:"lesson"}],study:[{title:"At Fillmore East (1971)",kind:"album",author:"The Allman Brothers Band",note:"Duane Allman's live bottleneck playing in open tuning, at length."},{title:"Dust My Broom (1951)",kind:"album",author:"Elmore James",url:"https://en.wikipedia.org/wiki/Elmore_James",note:"The defining open-tuning slide riff of electric blues."},{title:"Revelator (2011)",kind:"album",author:"Tedeschi Trucks Band",note:'Derek Trucks\' open-E slide, including "Midnight in Harlem".'},{title:"How to Play Slide Guitar (Parts 1 and 2)",kind:"lesson",author:"Mike Levine (Yamaha Hub)",url:"https://hub.yamaha.com/how-to-play-slide-guitar-part-2/",note:"A free walk-through of setup, tunings, muting, vibrato and finger choice."}],cites:["s1","s2","s3","s4","s5","s6","s7","s8"],blocks:[{type:"tab",id:"slide-guitar-open-g",title:"Open G chord slides",instr:"guitar",tuning:"D2 G2 D3 G3 B3 D4",bpm:76,grid:3,notes:[[0,3,11,1,"I"],[0,2,11,1,"M"],[0,1,11,1,"A"],[1,3,12,5,"s,v"],[1,2,12,5,"s,v"],[1,1,12,5,"s,v"],[6,1,15,2,"s"],[8,1,12,1,"s"],[9,2,12,3,"M,v"],[12,3,12,3,"I,v"],[15,3,10,2,"s"],[17,4,12,1,"P"],[18,4,10,3,"s"],[21,5,0,3,"P"],[21,4,0,3,"P"],[21,3,0,3,"P"]],note:"Slide the three-string chord from one fret below into the 12th fret and add vibrato. Keep the slide right over the fret wire, and let a finger trail behind it so the strings behind the slide stay quiet.",cites:["s2","s4"]},{type:"tab",id:"slide-guitar-open-d",title:"Open D single notes",instr:"guitar",tuning:"D2 A2 D3 F#3 A3 D4",bpm:72,grid:4,notes:[[0,1,10,1,"I"],[1,1,12,3,"s,v"],[4,2,12,2,"M"],[6,2,15,2,"s"],[8,2,12,2,"s"],[10,3,12,2,"I"],[12,3,10,2,"s"],[14,4,12,2,"P"],[16,4,10,1,"P"],[17,4,12,7,"s,v"],[24,6,0,8,"D"],[24,5,0,8,"D"],[24,4,0,8,"D"],[24,3,0,8,"D"],[24,2,0,8,"D"],[24,1,0,8,"D"]],note:"Single notes around the 12th fret, ending on the open D chord. Pluck with your fingers and rest the unused picking-hand fingers on the strings next to the one you play, so only one note sounds at a time.",cites:["s2","s5","s8"]},{type:"tab",id:"slide-guitar-standard",title:"Standard-tuning slide melody",instr:"guitar",bpm:80,grid:4,notes:[[0,1,7,1,"I"],[1,1,9,3,"s,v"],[4,1,12,2,"s"],[6,1,10,2,"s"],[8,1,9,4,"s,v"],[12,2,10,2,"M"],[14,2,8,2,"s"],[16,2,10,2,"s"],[18,2,5,2,"s"],[20,3,7,1,"I"],[21,3,6,3,"s"],[24,3,2,8,"s,v"]],note:"Standard tuning suits single-note lines. Each slide note is reached by gliding from the note before it on the same string, and the vibrato notes sit right over the fret wire.",cites:["s1","s3"]}]}),LEARN.technique({id:"jazz-voicings",name:"Shell and drop-2 voicings",family:"Harmony",level:"Intermediate",instr:"guitar",summary:"Jazz guitarists thin chords down to the notes that matter. Shell voicings keep the root, 3rd and 7th, drop-2 voicings spread a four-note chord over four neighbouring strings, and moving the 3rds and 7ths by step from chord to chord makes the changes sound connected.",how:["Build shells from the root, 3rd and 7th and leave out the 5th. The 3rd and 7th (the guide tones) tell the ear whether a chord is major 7, minor 7 or dominant 7.","Learn a ii–V–I in C with shells: Dm7 and Cmaj7 with the root on the 5th string, G7 with the root on the 6th string. All three sit within a few frets.","Follow the guide tones: the 7th of Dm7 (C) falls a half step to the 3rd of G7 (B), and the 7th of G7 (F) falls a half step to the 3rd of Cmaj7 (E).","Build a drop-2 voicing by taking a close-position four-note chord and moving its second-highest note down an octave. Cmaj7 as C-E-G-B becomes G-C-E-B, which fits the top four strings.",'Comp in time. Try a short chord on every beat, the four-to-the-bar style Freddie Green played with Count Basie, then the Charleston rhythm: beat 1 and the "&" of 2.'],mistakes:["Grabbing full six-string grips: they crowd the bass and fill up the space. The bassist has the root, so many comping players drop it or keep it low and light.","Jumping around the neck between chords: pick voicings where the 3rds and 7ths move by a half step or stay put.","Letting comping chords ring into the soloist: keep them short and leave gaps."],used:"Big-band rhythm guitar, above all Freddie Green with the Count Basie Orchestra (for example on April in Paris), and small-group comping behind soloists and singers.",sources:[{id:"s1",title:"LJS 53: How to Improve Your Jazz Solos By Using Guide Tones",author:"Brent Vaartstra",site:"Learn Jazz Standards",year:2017,url:"https://www.learnjazzstandards.com/ljs-podcast/learn-jazz-theory/ljs-53-improve-jazz-solos-using-guide-tones/",kind:"lesson"},{id:"s2",title:"Unlocking Jazz Guitar Chord Voicings: A Practical Guide",site:"TrueFire",url:"https://truefire.com/learn/unlocking-jazz-guitar-chord-voicings",kind:"lesson"},{id:"s3",title:"Chord Voicings Crash Course! Everything You Should Know About Chord Voicings",author:"James Melton",site:"Learn Jazz Standards",year:2025,url:"https://www.learnjazzstandards.com/blog/chord-voicings/",kind:"lesson"},{id:"s4",title:"Ultimate Jazz Comping 101: Learn To Comp Like A Jazz Pro",author:"James Melton",site:"Learn Jazz Standards",year:2025,url:"https://www.learnjazzstandards.com/blog/what-is-jazz-comping/",kind:"lesson"},{id:"s5",title:"Freddie Green",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Freddie_Green",kind:"encyclopedia"},{id:"s6",title:"What Are Drop 2 Voicings",author:"Stef Ramin",site:"Jazz Guitar Licks",url:"https://www.jazz-guitar-licks.com/blog/drop-2-chord-voicings-guitar-diagrams-jazz-lesson.html",kind:"lesson"},{id:"s7",title:"Swing Lesson: Learn to Play Rhythm Guitar Like Freddie Green",author:"Nick Rossi",site:"Acoustic Guitar",year:2023,url:"https://acousticguitar.com/swing-lesson-learn-to-play-rhythm-guitar-like-freddie-green/",kind:"lesson"},{id:"s8",title:"Style Guide: Soul Jazz",author:"Shawn Purcell",site:"Premier Guitar",year:2012,url:"https://www.premierguitar.com/lessons/style-guide-soul-jazz?page=3",kind:"lesson"}],study:[{title:"All About Guide Tones",kind:"lesson",author:"Pete Weise (Premier Guitar, 2025)",url:"https://www.premierguitar.com/lessons/jazz/all-about-guide-tones",note:"Shows how the same 3rd-and-7th motion shapes melodic lines over a ii–V–I."},{title:"Jazz Chord Voicings (Music Theory for the 21st-Century Classroom)",kind:"book",author:"Robert Hutchinson",url:"https://musictheory.pugetsound.edu/mt21c/JazzChordVoicings.html",note:"A free open textbook chapter on shells, guide tones and voice leading."},{title:"April in Paris (1956)",kind:"album",author:"Count Basie Orchestra with Freddie Green",note:"The reference recording for four-to-the-bar big-band rhythm guitar."},{title:"Chord Chemistry",kind:"book",author:"Ted Greene",note:"The classic guitar voicing encyclopedia, deep enough for years of study."}],cites:["s1","s2","s3","s4","s5","s6","s7","s8"],blocks:[{type:"shapes",title:"Shell voicings: ii–V–I in C",shapes:[{name:"Dm7",frets:"x 5 3 5 x x"},{name:"G7",frets:"3 x 3 4 x x"},{name:"Cmaj7",frets:"x 3 2 4 x x"}],note:"Root, 3rd and 7th only. The upper two notes go F and C, then F and B, then E and B: each guide tone moves a half step or stays where it is.",cites:["s1","s2"]},{type:"shapes",title:"Drop-2 voicings on the top four strings",shapes:[{name:"Dm7",frets:"x x 7 7 6 8"},{name:"G7",frets:"x x 5 7 6 7"},{name:"Cmaj7",frets:"x x 5 5 5 7"},{name:"A7",frets:"x x 5 6 5 5"}],note:"Four-note chords with the second-highest note dropped an octave. Played in order, most voices move by a step or less, and A7 leads back to Dm7.",cites:["s3","s6"]},{type:"tab",id:"jazz-voicings-four-to-the-bar",title:"Four-to-the-bar shells",instr:"guitar",bpm:132,grid:3,notes:[[0,5,5,2,"D"],[0,4,3,2,"D"],[0,3,5,2,"D"],[3,5,5,2,"D"],[3,4,3,2,"D"],[3,3,5,2,"D"],[6,5,5,2,"D"],[6,4,3,2,"D"],[6,3,5,2,"D"],[9,5,5,2,"D"],[9,4,3,2,"D"],[9,3,5,2,"D"],[12,6,3,2,"D"],[12,4,3,2,"D"],[12,3,4,2,"D"],[15,6,3,2,"D"],[15,4,3,2,"D"],[15,3,4,2,"D"],[18,6,3,2,"D"],[18,4,3,2,"D"],[18,3,4,2,"D"],[21,6,3,2,"D"],[21,4,3,2,"D"],[21,3,4,2,"D"],[24,5,3,2,"D"],[24,4,2,2,"D"],[24,3,4,2,"D"],[27,5,3,2,"D"],[27,4,2,2,"D"],[27,3,4,2,"D"],[30,5,3,2,"D"],[30,4,2,2,"D"],[30,3,4,2,"D"],[33,5,3,2,"D"],[33,4,2,2,"D"],[33,3,4,2,"D"],[36,5,3,2,"D"],[36,4,2,2,"D"],[36,3,4,2,"D"],[39,5,3,2,"D"],[39,4,2,2,"D"],[39,3,4,2,"D"],[42,5,3,2,"D"],[42,4,2,2,"D"],[42,3,4,2,"D"],[45,5,3,2,"D"],[45,4,2,2,"D"],[45,3,4,2,"D"]],note:"A short, even chord on every beat, in the big-band style. Let each chord go just before the next beat so the rhythm stays crisp.",cites:["s5","s7"]},{type:"tab",id:"jazz-voicings-charleston",title:"Charleston comping with drop-2 chords",instr:"guitar",bpm:132,grid:3,notes:[[0,4,7,3,"D"],[0,3,7,3,"D"],[0,2,6,3,"D"],[0,1,8,3,"D"],[5,4,7,2,"D,acc"],[5,3,7,2,"D,acc"],[5,2,6,2,"D,acc"],[5,1,8,2,"D,acc"],[12,4,5,3,"D"],[12,3,7,3,"D"],[12,2,6,3,"D"],[12,1,7,3,"D"],[17,4,5,2,"D,acc"],[17,3,7,2,"D,acc"],[17,2,6,2,"D,acc"],[17,1,7,2,"D,acc"],[24,4,5,3,"D"],[24,3,5,3,"D"],[24,2,5,3,"D"],[24,1,7,3,"D"],[29,4,5,2,"D,acc"],[29,3,5,2,"D,acc"],[29,2,5,2,"D,acc"],[29,1,7,2,"D,acc"],[36,4,5,3,"D"],[36,3,6,3,"D"],[36,2,5,3,"D"],[36,1,5,3,"D"],[41,4,5,2,"D,acc"],[41,3,6,2,"D,acc"],[41,2,5,2,"D,acc"],[41,1,5,2,"D,acc"]],note:'Dm7, G7, Cmaj7, A7 on the top four strings. Each bar is a chord on beat 1 and a short accented chord on the swung "&" of 2, the Charleston rhythm.',cites:["s4","s8"]}]}),LEARN.technique({id:"chord-embellishments",name:"Chord embellishments",family:"Harmony",level:"Intermediate",instr:"guitar",summary:"Hold a chord shape and decorate it with hammer-ons, pull-offs, slides and short melodic fills played inside or right around the shape. It is the soul and R&B rhythm style of Curtis Mayfield and Steve Cropper that Jimi Hendrix built on, and that players such as John Mayer still use.",how:["Choose a small shape you can hold, such as a three-string triad, and keep the fingers that make it pressed down.","Use a free finger to hammer on and pull off the notes next to the chord tones: the 4th falling to the 3rd, and the 6th and 9th around the 5th and the root.","Slide into triads and sixths from a fret below, and try double-stops hammered on from a step below, played short and sharp in the Steve Cropper manner.","Mix chord tones and single-note lines in one part. Hendrix played rhythm chords and lead lines together and often fretted 6th-string bass notes with his thumb over the neck, which frees the other fingers for fills.","Keep it understated: short fills between vocal lines, with the chord back on the beat. Curtis Mayfield is known for exactly this kind of restrained fill-and-chord playing."],mistakes:["Letting go of the chord to play the fill: the harmony disappears. Keep the anchor fingers down and move only the free finger.","Filling every gap: the part crowds the singer. Play a fill every bar or two and let the chord carry the rest.","Late hammer-ons: the ornament drags behind the beat. Pick the first note right on time and keep the hammer quick and short."],used:'Soul and R&B guitar from Curtis Mayfield with The Impressions, Steve Cropper (Sam and Dave\'s "Soul Man"), Marv Tarplin and Cornell Dupree (Aretha Franklin\'s "Respect"), Jimi Hendrix ("Little Wing", "The Wind Cries Mary") and, later, John Mayer.',sources:[{id:"s1",title:"Little Wing",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Little_Wing",kind:"encyclopedia"},{id:"s2",title:"Hendrix Rhythms Made Easy",author:"Jon MacLennan",site:"Premier Guitar",year:2020,url:"https://www.premierguitar.com/lessons/rhythm/jimi-hendrix-rhythm-guitar",kind:"lesson"},{id:"s3",title:"Curtis Mayfield",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Curtis_Mayfield",kind:"encyclopedia"},{id:"s4",title:"Playing Soul Guitar Rhythm",author:"Shawn Persinger",site:"Premier Guitar",year:2023,url:"https://www.premierguitar.com/sweet-soul-music",kind:"lesson"},{id:"s5",title:"The Many Sides of John Mayer",author:"Arthur Rotfeld",site:"Premier Guitar",year:2016,url:"https://www.premierguitar.com/lessons/many-sides-of-john-mayer",kind:"lesson"},{id:"s6",title:"The Acoustic Side of John Mayer",author:"Jon MacLennan",site:"Premier Guitar",year:2021,url:"https://www.premierguitar.com/lessons/acoustic-lessons/acoustic-john-mayer",kind:"lesson"},{id:"s7",title:"Mastering Guitar Double Stops: Essential Techniques",site:"TrueFire",year:2026,url:"https://blog.truefire.com/guitar-lessons/mastering-guitar-double-stops-essential-techniques/",kind:"lesson"}],study:[{title:"Axis: Bold as Love (1967)",kind:"album",author:"The Jimi Hendrix Experience",note:'Contains "Little Wing", the reference recording for chord-and-fill rhythm guitar.'},{title:"What The Ell? Lessons I Learned from Recreating John Mayer's Continuum",kind:"lesson",author:"Lindsay Ell (Premier Guitar, 2018)",url:"https://www.premierguitar.com/lessons/what-the-ell/lindsay-ell-john-mayer-continuum",note:"A player's notes on learning Mayer's Hendrix- and soul-influenced parts by ear."},{title:"Curtis (1970)",kind:"album",author:"Curtis Mayfield",note:"Mayfield's first solo album: his understated rhythm playing under a full band."},{title:"Experience Hendrix: The Best of Jimi Hendrix",kind:"book",author:"Hal Leonard (transcribed scores)",note:"Note-for-note transcriptions that show how the thumb-and-fingers approach works in real parts."}],cites:["s1","s2","s3","s4","s5","s6","s7"],blocks:[{type:"tab",id:"chord-embellishments-triads",title:"Hammer-ons inside D and G triads",instr:"guitar",bpm:72,grid:4,ring:!0,notes:[[0,3,7,4,"D"],[0,2,7,4,"D"],[0,1,5,4,"D"],[4,1,5,1],[5,1,7,1,"h"],[6,1,5,2,"p"],[8,2,8,1],[9,2,7,1,"p"],[10,3,7,2],[12,2,7,2,"U"],[12,1,5,2,"U"],[14,3,5,1],[15,3,7,1,"h"],[16,3,7,4,"D"],[16,2,8,4,"D"],[16,1,7,4,"D"],[20,1,7,1],[21,1,8,1,"h"],[22,1,7,2,"p"],[24,1,5,1],[25,1,7,1,"h"],[26,2,8,2],[28,3,7,1],[29,3,9,1,"h"],[30,3,7,2,"p"]],note:"Hold the D triad (bar 1) and the G triad (bar 2) on the top three strings, and let a free finger add the 6th, the 4th and the 9th with hammer-ons and pull-offs. The chord keeps ringing under each ornament.",cites:["s5","s6"]},{type:"tab",id:"chord-embellishments-double-stops",title:"Soul double-stops and sixths",instr:"guitar",bpm:84,grid:4,notes:[[0,3,5,1,"D"],[0,2,5,1,"D"],[1,3,7,2,"h"],[1,2,7,2,"h"],[4,3,5,1,"D"],[4,2,5,1,"D"],[5,3,7,2,"h"],[5,2,7,2,"h"],[8,3,10,1,"D"],[8,1,9,1,"D"],[9,3,11,2,"s"],[9,1,10,2,"s"],[12,3,9,2,"D"],[12,1,9,2,"D"],[14,3,7,2,"D"],[14,1,7,2,"D"],[16,3,2,1,"D"],[16,2,1,1,"D"],[17,3,4,2,"h"],[17,2,3,2,"h"],[20,3,2,1,"D"],[20,2,1,1,"D"],[21,3,4,2,"h"],[21,2,3,2,"h"],[24,3,3,1,"D"],[24,1,2,1,"D"],[25,3,4,2,"s"],[25,1,3,2,"s"],[28,3,4,3,"D,acc"],[28,2,3,3,"D,acc"]],note:"Two soul moves over D and G: a double-stop hammered on from a whole step below, and sixths slid into from a fret below. Keep everything short and right on the beat.",cites:["s4"]},{type:"tab",id:"chord-embellishments-chord-fill",title:"Chord, then fill",instr:"guitar",bpm:66,grid:4,ring:!0,notes:[[0,6,0,8,"D"],[0,5,2,8,"D"],[0,4,2,8,"D"],[0,3,0,8,"D"],[0,2,0,8,"D"],[0,1,0,8,"D"],[8,2,0,1],[9,2,3,1,"h"],[10,1,0,1],[11,1,3,1,"h"],[12,1,0,1,"p"],[13,2,3,1],[14,2,0,2,"p"],[16,6,3,6,"D"],[16,5,2,6,"D"],[16,4,0,6,"D"],[16,3,0,6,"D"],[16,2,0,6,"D"],[16,1,3,6,"D"],[22,2,0,1],[23,2,1,1,"h"],[24,2,0,2,"p"],[26,3,0,1],[27,3,2,1,"h"],[28,4,0,1],[29,4,2,1,"h"],[30,6,0,2]],note:"Strum Em or G on beat 1, then fill the bar with hammer-ons from the E minor pentatonic scale on strings inside the chord. The chord rings under the fill, blending rhythm and lead in one part.",cites:["s1","s2"]}]}),LEARN.technique({id:"string-muting",name:"String muting",family:"Rhythm",level:"Beginner",instr:"guitar",summary:"Both hands keep unwanted strings quiet: the fretting hand by touching strings without pressing them, the picking hand by resting on the strings you are not playing. The same touch gives you dead notes, the percussive clicks written as x in tab.",how:["Fretting hand: let the unused parts of your fingers lie lightly across the strings you are not playing. The thumb over the top of the neck can touch the low E.","To stop a note, release the pressure without lifting the finger off the string. The note dies at once instead of ringing on.","For a dead note, touch the string without pressing it to the fret, then pick it: you get a muffled click with no clear pitch.","Picking hand: rest the side of your palm near the bridge on the lower strings you are not using. Keep the weight light, or you will choke the notes you want.","Strum through muted strings to keep time. The percussive strokes fill out the rhythm and keep your strumming hand moving in the pocket.","A rake is a quick strum across muted strings that leads into a fretted note, giving the note a percussive run-up."],mistakes:["Lifting fingers right off the strings: open strings ring and chords sound out of tune. Release pressure but keep contact.","Pressing the palm too hard: the notes you want get choked. Rest the hand on the strings without pushing.","Checking only with a clean sound: with high gain, small leaks turn into noise and fast notes blur together. Practise muting with the amp set the way you play."],used:'Funk scratching, reggae and ska "skanks", tight rock and metal riffs, and any part where single notes are strummed through muted strings.',sources:[{id:"s1",title:"Left-hand muting",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Left-hand_muting",kind:"encyclopedia"},{id:"s2",title:"Chicken Pickin' for Rockers",author:"Jeff Jacobson",site:"Premier Guitar",year:2023,url:"https://www.premierguitar.com/lessons/country/chicken-pickin-for-rockers",kind:"lesson"},{id:"s3",title:"Clean Up Your Technique!",author:"Sam Bell",site:"Premier Guitar",year:2025,url:"https://www.premierguitar.com/lessons/clean-up-your-technique",kind:"lesson"},{id:"s4",title:"Ending Sonic Pollution: How to Make Simple Things Sound Good",author:"Rob Michael",site:"Premier Guitar",year:2022,url:"https://www.premierguitar.com/lessons/beginner/how-to-palm-mute?rebelltitem=17",kind:"lesson"},{id:"s5",title:"Twang 101: Truckerbilly Grooves",author:"Jason Loughlin",site:"Premier Guitar",year:2011,url:"https://www.premierguitar.com/twang-101-truckerbilly-grooves",kind:"lesson"},{id:"s6",title:"Learn To Play... Stevie Ray Vaughan Right-hand Technique",author:"Dan Holton",site:"Guitar.com",year:2018,url:"https://guitar.com/lessons/stevie-ray-right-hand-technique/",kind:"lesson"},{id:"s7",title:"Guitar Picking Technique: A Complete Guide to Mastering Your Craft",site:"TrueFire",url:"https://truefire.com/learn/guitar-picking-technique",kind:"lesson"}],study:[{title:"Ending Sonic Pollution (Premier Guitar column)",kind:"lesson",author:"Rob Michael",url:"https://www.premierguitar.com/lessons/beginner/how-to-palm-mute?rebelltitem=17",note:"Six short examples of strummed single notes and octaves muted by the fretting hand."},{title:"Funk Guitar in One Chord Shape or Less",kind:"lesson",author:"Shawn Persinger (Premier Guitar)",url:"https://www.premierguitar.com/funk-guitar-in-one-chord-shape-or-less",note:"Puts fretting-hand muting to work in choked and scratched funk rhythms."},{title:"Clean Up Your Technique!",kind:"lesson",author:"Sam Bell (Premier Guitar, 2025)",url:"https://www.premierguitar.com/lessons/clean-up-your-technique",note:"Muting with both hands under high gain, and why a noise gate cannot hide sloppy muting."}],cites:["s1","s2","s3","s4","s5","s6","s7"],blocks:[{type:"tab",id:"string-muting-chops",title:"Chops and muted upstrokes",instr:"guitar",bpm:90,grid:2,notes:[[0,6,3,1,"D,acc"],[0,5,5,1,"D,acc"],[0,4,5,1,"D,acc"],[1,6,3,1,"x,U"],[1,5,5,1,"x,U"],[1,4,5,1,"x,U"],[2,6,3,1,"D,acc"],[2,5,5,1,"D,acc"],[2,4,5,1,"D,acc"],[3,6,3,1,"x,U"],[3,5,5,1,"x,U"],[3,4,5,1,"x,U"],[4,5,3,1,"D,acc"],[4,4,5,1,"D,acc"],[4,3,5,1,"D,acc"],[5,5,3,1,"x,U"],[5,4,5,1,"x,U"],[5,3,5,1,"x,U"],[6,5,3,1,"D,acc"],[6,4,5,1,"D,acc"],[6,3,5,1,"D,acc"],[7,5,3,1,"x,U"],[7,4,5,1,"x,U"],[7,3,5,1,"x,U"],[8,5,5,1,"D,acc"],[8,4,7,1,"D,acc"],[8,3,7,1,"D,acc"],[9,5,5,1,"x,U"],[9,4,7,1,"x,U"],[9,3,7,1,"x,U"],[10,5,5,1,"D,acc"],[10,4,7,1,"D,acc"],[10,3,7,1,"D,acc"],[11,5,5,1,"x,U"],[11,4,7,1,"x,U"],[11,3,7,1,"x,U"],[12,5,3,1,"D,acc"],[12,4,5,1,"D,acc"],[12,3,5,1,"D,acc"],[13,5,3,1,"x,U"],[13,4,5,1,"x,U"],[13,3,5,1,"x,U"],[14,5,3,1,"D,acc"],[14,4,5,1,"D,acc"],[14,3,5,1,"D,acc"],[15,5,3,1,"x,U"],[15,4,5,1,"x,U"],[15,3,5,1,"x,U"]],note:"Strike each power chord on the beat and release the pressure at once so it stops short. The upstroke hits the same strings with the fingers relaxed, for a muted click. Release pressure, never contact.",cites:["s1","s5"]},{type:"tab",id:"string-muting-strummed-notes",title:"Strummed single notes",instr:"guitar",bpm:84,grid:2,notes:[[0,6,5,1,"x,D"],[0,5,5,1,"x,D"],[0,4,5,1,"D"],[0,3,5,1,"x,D"],[0,2,5,1,"x,D"],[0,1,5,1,"x,D"],[1,6,5,1,"x,U"],[1,5,5,1,"x,U"],[1,4,5,1,"x,U"],[1,3,5,1,"x,U"],[1,2,5,1,"x,U"],[1,1,5,1,"x,U"],[2,6,2,1,"x,D"],[2,5,2,1,"x,D"],[2,4,2,1,"D"],[2,3,2,1,"x,D"],[2,2,2,1,"x,D"],[2,1,2,1,"x,D"],[3,6,5,1,"x,U"],[3,5,5,1,"U"],[3,4,5,1,"x,U"],[3,3,5,1,"x,U"],[3,2,5,1,"x,U"],[3,1,5,1,"x,U"],[4,6,2,1,"x,D"],[4,5,2,1,"x,D"],[4,4,2,1,"x,D"],[4,3,2,1,"x,D"],[4,2,2,1,"x,D"],[4,1,2,1,"x,D"],[5,6,2,1,"x,U"],[5,5,2,1,"x,U"],[5,4,2,1,"U"],[5,3,2,1,"x,U"],[5,2,2,1,"x,U"],[5,1,2,1,"x,U"],[6,6,2,1,"x,D"],[6,5,2,1,"x,D"],[6,4,2,1,"x,D"],[6,3,2,1,"D"],[6,2,2,1,"x,D"],[6,1,2,1,"x,D"],[7,6,2,1,"x,U"],[7,5,2,1,"x,U"],[7,4,2,1,"x,U"],[7,3,2,1,"x,U"],[7,2,2,1,"x,U"],[7,1,2,1,"x,U"],[8,6,5,1,"x,D"],[8,5,5,1,"x,D"],[8,4,5,1,"D"],[8,3,5,1,"x,D"],[8,2,5,1,"x,D"],[8,1,5,1,"x,D"],[9,6,5,1,"x,U"],[9,5,5,1,"x,U"],[9,4,5,1,"x,U"],[9,3,5,1,"x,U"],[9,2,5,1,"x,U"],[9,1,5,1,"x,U"],[10,6,2,1,"x,D"],[10,5,2,1,"x,D"],[10,4,2,1,"D"],[10,3,2,1,"x,D"],[10,2,2,1,"x,D"],[10,1,2,1,"x,D"],[11,6,5,1,"x,U"],[11,5,5,1,"x,U"],[11,4,5,1,"U"],[11,3,5,1,"x,U"],[11,2,5,1,"x,U"],[11,1,5,1,"x,U"],[12,6,2,1,"x,D"],[12,5,2,1,"x,D"],[12,4,2,1,"x,D"],[12,3,2,1,"D"],[12,2,2,1,"x,D"],[12,1,2,1,"x,D"],[13,6,5,1,"x,U"],[13,5,5,1,"x,U"],[13,4,5,1,"U"],[13,3,5,1,"x,U"],[13,2,5,1,"x,U"],[13,1,5,1,"x,U"],[14,6,2,1,"x,D"],[14,5,2,1,"x,D"],[14,4,2,1,"D"],[14,3,2,1,"x,D"],[14,2,2,1,"x,D"],[14,1,2,1,"x,D"],[15,6,2,1,"x,U"],[15,5,2,1,"x,U"],[15,4,2,1,"x,U"],[15,3,2,1,"x,U"],[15,2,2,1,"x,U"],[15,1,2,1,"x,U"]],note:"Strum across all six strings and let only one fretted note through: the fretting finger frets its string while the rest of the finger and hand lie across the others. The melody moves between the 2nd and 5th frets; the empty strokes are pure muted clicks.",cites:["s4","s6"]},{type:"tab",id:"string-muting-rakes",title:"Rakes and muted chugs",instr:"guitar",bpm:80,grid:4,notes:[[0,4,8,1,"x,D"],[0,3,8,1,"x,D"],[0,2,8,1,"x,D"],[1,1,8,3,"D,v"],[4,5,0,1,"pm,D"],[5,5,0,1,"pm,U"],[6,5,0,1,"pm,D"],[7,5,0,1,"pm,U"],[8,4,5,1,"x,D"],[8,3,5,1,"x,D"],[8,2,5,1,"x,D"],[9,1,5,3,"D,v"],[12,5,0,1,"pm,D"],[13,5,0,1,"pm,U"],[14,5,0,1,"pm,D"],[15,5,0,1,"pm,U"],[16,4,7,1,"x,D"],[16,3,7,1,"x,D"],[17,2,8,3,"D,v"],[20,5,0,1,"pm,D"],[21,5,0,1,"pm,U"],[22,5,0,1,"pm,D"],[23,5,0,1,"pm,U"],[24,4,5,1,"x,D"],[24,3,5,1,"x,D"],[25,2,5,3,"D,v"],[28,5,3,2,"D"],[30,5,2,2,"D"]],note:"Each melody note follows a rake: drag the pick across two or three muted strings in one downstroke and land on the note. Between phrases, palm-mute the open A. Both hands keep everything else silent.",cites:["s1","s5"]}]}),LEARN.technique({id:"bass-root-fifth",name:"Root, fifth and octave bass lines",family:"Bass",level:"Beginner",instr:"bass",summary:"The bass outlines each chord and locks in with the kick drum. Roots, fifths and octaves are the core notes for that job, and an approach note on the last beat leads the ear into the next chord.",how:["Start with roots only and follow the kick drum: play the root of the chord where the kick hits. Doubling the kick pattern makes the groove solid.","Add the fifth. On a bass tuned in fourths it sits two frets up on the next higher string, or at the same fret on the next lower string.","For a country feel, play the root on beat 1 and the fifth on beat 3, the way bluegrass and traditional country bass lines often do.","Add the octave: two strings up and two frets up from the root. Pumping between root and octave is the classic disco move.","On the last beat before a chord change, play an approach note a half step or a whole step above or below the next root.","Root and fifth fit every chord in a major key except the diminished vii chord, whose fifth is flat."],mistakes:["Playing busy lines against the kick: the groove gets cluttered. Start from the kick pattern and add notes only where they help.","Using chromatic approach notes on every change in country: the style stays mostly diatonic. Save chromatic notes for a few changes.","Playing the regular fifth on the vii chord: it clashes. Use the flat fifth or stay on the root."],used:"Bluegrass and traditional country (root and fifth on beats 1 and 3), rock and pop bass, disco octave lines, and soul grooves built on root, fifth and octave.",sources:[{id:"s1",title:"Mastering Country Bass Lines: Roots, Fifths, and Chord Function Explained",author:"Ryan Madora",site:"No Treble",year:2025,url:"https://www.notreble.com/buzz/2025/05/21/mastering-country-bass-lines-roots-fifths-and-chord-function-explained/",kind:"lesson"},{id:"s2",title:"Getting Your Groove On With Only Root And Fifth",author:"Mark Smith",site:"TalkingBass",year:2015,url:"https://www.talkingbass.net/getting-your-groove-on-with-only-root-and-fifth/",kind:"lesson"},{id:"s3",title:"Creating Basslines: Bass Drum Patterns",author:"Mark Smith",site:"TalkingBass",year:2014,url:"https://www.talkingbass.net/creating-basslines-1-bass-drum-patterns-pedalling/",kind:"lesson"},{id:"s4",title:"Using Approach Notes To Improve Your Bass Lines",author:"Mark Smith",site:"TalkingBass",year:2015,url:"https://www.talkingbass.net/approach-notes/",kind:"lesson"},{id:"s5",title:"Disco Bass Octaves",author:"Mark Smith",site:"TalkingBass",year:2016,url:"https://www.talkingbass.net/disco-bass-octaves/",kind:"lesson"},{id:"s6",title:"Bassline",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Bassline",kind:"encyclopedia"}],study:[{title:"Build Better Bass Lines With This Root–Fifth–Octave Pinky Exercise",kind:"lesson",author:"Ryan Madora (No Treble, 2026)",url:"https://www.notreble.com/buzz/2026/03/25/build-better-bass-lines-with-this-root-fifth-octave-pinky-exercise/",note:"A root-fifth-octave pattern through a progression, with songs that use it."},{title:"Bass Line Creation lesson series",kind:"lesson",author:"Mark Smith (TalkingBass)",url:"https://www.talkingbass.net/bass-line-creation/",note:"Free lessons in a sensible order: roots, chord tones, approach notes, kick-drum lines, octaves."},{title:"Using Double Approach Notes In Your Bass Lines",kind:"lesson",author:"Mark Smith (TalkingBass)",url:"https://www.talkingbass.net/using-double-approach-notes-in-your-bass-lines/",note:"The next step after single approach notes."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"bass-root-fifth-country",title:"Country root and fifth",instr:"bass",bpm:104,grid:2,notes:[[0,4,3,2,"I"],[4,3,5,2,"M"],[8,3,3,2,"I"],[12,4,3,2,"M"],[16,3,5,2,"I"],[20,4,5,2,"M"],[24,4,3,2,"I"],[28,3,5,2,"M"]],note:"G, C, D, G. Root on beat 1, fifth on beat 3, leaving beats 2 and 4 to the snare. On C and D the fifth is the same fret one string lower, so the hand barely moves.",cites:["s1","s6"]},{type:"tab",id:"bass-root-fifth-octaves",title:"Disco octaves",instr:"bass",bpm:112,grid:4,notes:[[0,4,5,2,"I"],[2,2,7,2,"M"],[4,4,5,2,"I"],[6,2,7,2,"M"],[8,4,5,2,"I"],[10,2,7,2,"M"],[12,4,5,2,"I"],[14,2,7,2,"M"],[16,3,5,2,"I"],[18,1,7,2,"M"],[20,3,5,2,"I"],[22,1,7,2,"M"],[24,3,5,2,"I"],[26,1,7,2,"M"],[28,3,5,2,"I"],[30,4,4,2,"M"]],note:'Am then Dm. Root on the beat, octave on the "&", two strings and two frets up. The last note is a half-step approach back to A. Mute the low string with your fretting hand as you jump.',cites:["s5","s4"]},{type:"tab",id:"bass-root-fifth-approach",title:"Kick-drum rhythm with approach notes",instr:"bass",bpm:96,grid:2,notes:[[0,3,3,2,"I"],[3,3,3,1,"M"],[4,4,3,2,"I"],[6,4,4,2,"M"],[8,4,5,2,"I"],[11,4,5,1,"M"],[12,3,7,2,"I"],[14,4,0,2,"M"],[16,4,1,2,"I"],[19,4,1,1,"M"],[20,3,3,2,"I"],[22,4,2,2,"M"],[24,4,3,2,"I"],[27,4,3,1,"M"],[28,3,5,2,"I"],[30,3,2,2,"M"]],note:'C, Am, F, G. Roots on beat 1 and the "&" of 2 with the kick, the fifth on beat 3, then a half-step approach on beat 4 into the next root.',cites:["s3","s4"]}]}),LEARN.technique({id:"walking-bass",name:"Walking bass lines",family:"Bass",level:"Intermediate",instr:"bass",summary:"A walking bass line moves in steady quarter notes, one per beat, outlining each chord and connecting it to the next. Chord tones on the strong beats and a half-step approach on beat 4 are the backbone of the style.",how:["Play one note per beat with an even, swung quarter-note feel. Before adding notes, walk roots and fifths on beats 1 and 3.","Land on the root on beat 1 whenever the chord changes.","Fill beats 2 and 3 with chord tones. Root, 3rd and 5th is the simplest outline for the first three beats.","On beat 4, play a note a half step above or below the next chord's root, so the line leans into the change.","Once that is steady, mix in scale steps and chromatic passing notes, for example Mixolydian runs over the chords of a blues.","Practise over a ii–V–I and a 12-bar blues, the usual practice vehicles for walking."],mistakes:["Missing the root on beat 1: the harmony gets vague. Check that every chord change lands on its root before adding variety.","Uneven quarter notes: steady time matters more than clever note choice. Practise with the metronome clicking on beats 2 and 4.","Repeating root, 3rd, 5th, approach in every bar: it starts to sound mechanical. Swap in scale runs and descending lines once the basic shape is solid."],used:"Jazz from swing to bebop, blues, rockabilly and boogie-woogie. For listening, start with landmark jazz bassists such as Paul Chambers on Miles Davis's Kind of Blue.",sources:[{id:"s1",title:"Walking Bass Line Writing Step By Step",author:"Steve Nixon",site:"FreeJazzLessons.com",url:"https://www.freejazzlessons.com/?p=53401",kind:"lesson"},{id:"s2",title:"Walking Bass Lines The Easy Way With This Simple Hack",author:"Mark Smith",site:"TalkingBass",year:2018,url:"https://www.talkingbass.net/walking-bass-lines-made-easy/",kind:"lesson"},{id:"s3",title:"Beginning Walking Bass Lines: A Basic Introduction",author:"Mark Smith",site:"TalkingBass",year:2014,url:"https://www.talkingbass.net/walking-bass-lines-introduction/",kind:"lesson"},{id:"s4",title:"Walking Bass Through a 12 Bar Blues",author:"Mark Smith",site:"TalkingBass",year:2015,url:"https://www.talkingbass.net/walking-bass-through-a-12-bar-blues/",kind:"lesson"},{id:"s5",title:"Walking bass (Bassline)",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Walking_bass",kind:"encyclopedia"},{id:"s6",title:"Bass Lines: The Walking Bass Line, Part 2",author:"Jaime David Vazquez",site:"Bass Musician Magazine",year:2016,url:"https://bassmusicianmagazine.com/2016/03/bass-lines-by-jaime-david-vazquez-the-walking-bass-line-part-2/amp/",kind:"article"}],study:[{title:"Building Walking Bass Lines",kind:"book",author:"Ed Friedland (Hal Leonard)",url:"https://bassmusicianmagazine.com/2020/02/review-hal-leonards-building-walking-bass-lines-by-ed-friedland/amp/",note:"Moves step by step from roots to fifths to chromatic and scale approaches, with play-along audio (link is a review of the book)."},{title:"Ray Brown's Bass Method",kind:"book",author:"Ray Brown (Hal Leonard)",note:"Scales, patterns and exercises from one of the great jazz rhythm-section bassists."},{title:"Kind of Blue (1959)",kind:"album",author:"Miles Davis, with Paul Chambers on bass",url:"https://en.wikipedia.org/wiki/Kind_of_Blue",note:'"Freddie Freeloader" is a 12-bar blues with a model walking line.'},{title:"Walking bass lessons",kind:"lesson",author:"Mark Smith (TalkingBass)",url:"https://www.talkingbass.net/walking-bass-lessons/",note:"Free lessons from first steps to jazz blues and standards."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"walking-bass-ii-v-i",title:"ii–V–I in C",instr:"bass",bpm:120,grid:2,notes:[[0,3,5,2,"I"],[2,2,3,2,"M"],[4,2,7,2,"I"],[6,2,6,2,"M"],[8,2,5,2,"I"],[10,2,3,2,"M"],[12,3,5,2,"I"],[14,3,4,2,"M"],[16,3,3,2,"I"],[18,3,5,2,"M"],[20,2,2,2,"I"],[22,2,5,2,"M"],[24,2,7,2,"I"],[26,2,5,2,"M"],[28,2,2,2,"I"],[30,2,1,2,"M"]],note:"Dm7, G7, Cmaj7, Cmaj7. Roots on every beat 1, chord tones in the middle, and a half-step approach on beat 4 (A-flat into G, C-sharp into C, E-flat back into D). Swing the quarters.",cites:["s1","s2"]},{type:"tab",id:"walking-bass-blues-start",title:"Blues in F, bars 1 to 4",instr:"bass",bpm:120,grid:2,notes:[[0,4,1,2,"I"],[2,4,5,2,"M"],[4,3,3,2,"I"],[6,3,2,2,"M"],[8,3,1,2,"I"],[10,2,0,2,"M"],[12,2,3,2,"I"],[14,2,2,2,"M"],[16,4,1,2,"I"],[18,4,3,2,"M"],[20,4,5,2,"I"],[22,3,3,2,"M"],[24,2,3,2,"I"],[26,2,1,2,"M"],[28,3,3,2,"I"],[30,4,2,2,"M"]],note:"F7, Bb7, F7, F7. Bar 3 is a Mixolydian run up from the root. The last note approaches F so the exercise loops; in a full 12-bar, aim it at B-flat for the Bb7 in bar 5 instead.",cites:["s4","s6"]},{type:"tab",id:"walking-bass-blues-turnaround",title:"Blues in F, bars 9 to 12",instr:"bass",bpm:120,grid:2,notes:[[0,4,3,2,"I"],[2,3,1,2,"M"],[4,3,5,2,"I"],[6,3,4,2,"M"],[8,3,3,2,"I"],[10,2,2,2,"M"],[12,2,5,2,"I"],[14,2,4,2,"M"],[16,2,3,2,"I"],[18,2,1,2,"M"],[20,2,0,2,"I"],[22,3,0,2,"M"],[24,4,3,2,"I"],[26,3,1,2,"M"],[28,3,3,2,"I"],[30,4,4,2,"M"]],note:"Gm7, C7, then two chords per bar: F7 to D7 and Gm7 to C7. When the chord lasts two beats, play its root and then an approach note. The last note leads back to Gm7 for looping.",cites:["s1","s4"]}]}),LEARN.technique({id:"slap-bass",name:"Slap and pop bass",family:"Bass",level:"Intermediate",instr:"bass",summary:"The thumb strikes the low strings like a bass drum and a finger pulls the high strings so they snap against the frets like a snare. Larry Graham developed the style, which he described as thumping and plucking, after his mother's band dropped its drummer and he set out to cover the drum parts on bass.",how:["Thumb: rotate the forearm and strike the E or A string with the bony joint of your thumb near the base of the neck, where it meets the body.","Choose a thumb motion: bounce straight back off the string, the approach linked to Mark King, or follow through to rest on the next string, linked to Marcus Miller and Victor Wooten.","Pop: catch the D or G string with the tip of your index or middle finger and pull it away from the body so it snaps back against the frets.","Start with octaves: slap the root on the E or A string and pop the same note an octave higher on the D or G string, two strings over and two frets up.","Add ghost notes: rest a fretting-hand finger lightly on the string and slap or pop it for a pitchless thump. They work like a second drum part.","Control note length with the fretting hand: ease off the pressure to choke a note short."],mistakes:["Slapping over the pickups: the note sounds thin and the thumb has nowhere to bounce. Aim near the base of the neck.","Pulling pops too far: the volume jumps and the timing suffers. A small, quick pull is enough.","Letting every note ring: the line turns into a blur. Choke notes with the fretting hand and use ghost notes to fill the gaps."],used:'Funk, fusion and pop bass: Larry Graham with Sly and the Family Stone ("Thank You (Falettinme Be Mice Elf Agin)") and Graham Central Station, Stanley Clarke, Mark King with Level 42, Marcus Miller and Victor Wooten.',sources:[{id:"s1",title:"Interview: Larry Graham, Sheer Energy",author:"James Volpe Rotondi",site:"Premier Guitar",year:2012,url:"https://www.premierguitar.com/artists/interview-larry-graham-sheer-energy",kind:"interview"},{id:"s2",title:"Slapping (music)",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Slapping_(music)",kind:"encyclopedia"},{id:"s3",title:"How To Play Slap Bass: Getting Started",author:"Mark J Smith",site:"TalkingBass",year:2013,url:"https://www.talkingbass.net/how-to-play-slap-bass/",kind:"lesson"},{id:"s4",title:"How To Play Slap Bass: Using Ghost Notes",author:"Mark J Smith",site:"TalkingBass",year:2014,url:"https://www.talkingbass.net/play-slap-bass-ghost-notes/",kind:"lesson"},{id:"s5",title:"Slap Technique: Bounce vs Rest Stroke",author:"Mark J Smith",site:"TalkingBass",year:2016,url:"https://www.talkingbass.net/slap-technique-bounce-vs-rest-stroke/",kind:"lesson"},{id:"s6",title:"Mark King (musician)",site:"Wikipedia",url:"https://en.wikipedia.org/wiki/Mark_King_(musician)",kind:"encyclopedia"}],study:[{title:"Thank You (Falettinme Be Mice Elf Agin) (1969)",kind:"album",author:"Sly and the Family Stone",url:"https://en.wikipedia.org/wiki/Thank_You_(Falettinme_Be_Mice_Elf_Agin)",note:"Larry Graham's thumping is all over this number-one single."},{title:"Slap bass lessons",kind:"lesson",author:"Mark Smith (TalkingBass)",url:"https://www.talkingbass.net/slap-bass-lessons/",note:"A free step-by-step path from first slaps to ghost notes, hammer-ons and double thumbing."},{title:"Lopsy Lu: How Stanley Clarke Changed Slap Bass Forever",kind:"lesson",author:"TalkingBass",url:"https://www.talkingbass.net/lopsy-lu-how-stanley-clarke-changed-slap-bass-forever/",note:"A breakdown of a slap intro that influenced Mark King and later players."},{title:"Double Thumb Slap Technique",kind:"lesson",author:"TalkingBass",url:"https://www.talkingbass.net/double-thumb-slap-technique/",note:"The up-and-down thumb technique pioneered by Victor Wooten, once the basics are steady."}],cites:["s1","s2","s3","s4","s5","s6"],blocks:[{type:"tab",id:"slap-bass-octaves",title:"Slap and pop octaves",instr:"bass",bpm:88,grid:4,notes:[[0,4,0,2,"slap"],[2,2,2,2,"pop"],[4,4,0,2,"slap"],[6,2,2,2,"pop"],[8,4,0,2,"slap"],[10,2,2,2,"pop"],[12,4,0,2,"slap"],[14,2,2,2,"pop"],[16,4,3,2,"slap"],[18,2,5,2,"pop"],[20,4,3,2,"slap"],[22,2,5,2,"pop"],[24,3,0,2,"slap"],[26,1,2,2,"pop"],[28,3,0,2,"slap"],[30,1,2,2,"pop"]],note:"Thumb on the root, pop on the octave two strings over and two frets up: E in bar 1, then G and A. Let each note last its full eighth note, then choke it.",cites:["s2","s3"]},{type:"tab",id:"slap-bass-ghosts",title:"Thumb, ghost, pop, ghost",instr:"bass",bpm:84,grid:4,notes:[[0,4,0,1,"slap"],[1,4,2,1,"slap,x"],[2,2,2,1,"pop"],[3,2,2,1,"pop,x"],[4,4,0,1,"slap"],[5,4,2,1,"slap,x"],[6,2,2,1,"pop"],[7,2,2,1,"pop,x"],[8,4,3,1,"slap"],[9,4,3,1,"slap,x"],[10,2,5,1,"pop"],[11,2,5,1,"pop,x"],[12,3,0,1,"slap"],[13,3,2,1,"slap,x"],[14,1,2,1,"pop"],[15,1,2,1,"pop,x"],[16,4,0,1,"slap"],[17,4,2,1,"slap,x"],[18,2,2,1,"pop"],[19,2,2,1,"pop,x"],[20,4,0,1,"slap"],[21,4,2,1,"slap,x"],[22,2,2,1,"pop"],[23,2,2,1,"pop,x"],[24,3,5,1,"slap"],[25,3,5,1,"slap,x"],[26,1,7,1,"pop"],[27,1,7,1,"pop,x"],[28,3,2,1,"slap"],[29,3,2,1,"slap,x"],[30,1,4,1,"pop"],[31,1,4,1,"pop,x"]],note:"Fill every sixteenth: slap the root, ghost-slap the muted string, pop the octave, ghost-pop it muted. The ghosts should be clearly quieter, more drum than note.",cites:["s4"]},{type:"tab",id:"slap-bass-hammer-riff",title:"E minor riff with hammer-ons",instr:"bass",bpm:92,grid:4,notes:[[0,4,0,1,"slap"],[1,4,2,1,"slap,x"],[2,3,0,1,"slap"],[3,3,2,1,"h"],[4,2,2,2,"pop"],[6,4,0,1,"slap"],[7,4,2,1,"slap,x"],[8,3,5,1,"slap"],[9,3,7,1,"h"],[10,1,4,2,"pop"],[12,4,3,1,"slap"],[13,4,5,1,"h"],[14,2,5,1,"pop"],[15,2,2,1,"pop"],[16,4,0,1,"slap"],[17,4,2,1,"slap,x"],[18,3,0,1,"slap"],[19,3,2,1,"h"],[20,2,2,2,"pop"],[22,4,0,1,"slap"],[23,4,2,1,"slap,x"],[24,3,2,2,"slap"],[26,2,2,1,"pop"],[27,2,2,1,"pop,x"],[28,4,0,2,"slap"],[30,4,0,1,"slap"],[31,4,2,1,"h"]],note:"Slap a note, then hammer the next one with the fretting hand instead of slapping again, so the line flows between thumb, hammer and pop. Keep the ghost notes light.",cites:["s2","s6"]}]});